-- bản dịch exercises-vi.jsonl và danh sách ảnh đã tải lên Cloudinary (cloudinary-da-tai.txt). Đừng sửa tay.
-- Bài mới nạp ở trạng thái chưa duyệt: is_active=false, is_draft=true (design-thu-vien-bai-v1.md §4.2).

INSERT INTO exercises (slug, name_en, muscle_groups, equipment, steps_vi, mistakes_vi, analyzable, is_active, is_draft) VALUES
  ('3-4-sit-up', '3/4 sit-up', '{CORE,LOWER_BACK}', '{}', ARRAY['Nằm ngửa, gối co, bàn chân đặt phẳng trên sàn.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết cơ bụng, từ từ nâng thân trên khỏi sàn, cuộn người về phía trước tới khi thân tạo góc 45 độ.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('45-side-bend', '45° side bend', '{CORE}', '{}', ARRAY['Đứng, hai chân rộng bằng vai, hai tay thẳng buông dọc hai bên người.', 'Giữ lưng thẳng và siết cơ lõi, từ từ nghiêng thân sang một bên, đưa tay xuống gần đầu gối.', 'Dừng một nhịp ở dưới cùng, rồi từ từ trở về tư thế ban đầu.', 'Lặp lại sang bên kia.', 'Tiếp tục luân phiên hai bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('air-bike', 'air bike', '{CORE}', '{}', ARRAY['Nằm ngửa, hai tay đặt sau đầu.', 'Nâng hai chân khỏi sàn, gập gối một góc 90 độ.', 'Đưa khuỷu tay phải về phía đầu gối trái, đồng thời duỗi thẳng chân phải.', 'Trở về tư thế ban đầu, lặp lại bên kia: đưa khuỷu tay trái về phía đầu gối phải, đồng thời duỗi thẳng chân trái.', 'Tiếp tục luân phiên hai bên theo kiểu đạp xe đủ số lần mong muốn.'], '{}', false, false, true),
  ('all-fours-squad-stretch', 'all fours squad stretch', '{QUADS,HAMSTRINGS,GLUTES}', '{}', ARRAY['Quỳ bốn chân, hai tay đặt ngay dưới vai, hai đầu gối ngay dưới hông.', 'Duỗi thẳng một chân ra sau, giữ gối gập và bàn chân gập lại.', 'Từ từ hạ hông xuống sàn, cảm nhận căng ở đùi trước.', 'Giữ tư thế này 20-30 giây.', 'Đổi chân và kéo giãn bên kia.'], '{}', false, false, true),
  ('alternate-heel-touchers', 'alternate heel touchers', '{CORE}', '{}', ARRAY['Nằm ngửa, gối co, bàn chân đặt phẳng trên sàn.', 'Dang thẳng hai tay sang hai bên, song song với sàn.', 'Siết cơ bụng, nâng vai khỏi sàn và đưa tay phải chạm gót chân phải.', 'Trở về tư thế ban đầu, lặp lại bên trái: đưa tay trái chạm gót chân trái.', 'Tiếp tục luân phiên hai bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('alternate-lateral-pulldown', 'alternate lateral pulldown', '{LATS,BICEPS,UPPER_BACK}', '{CABLE}', ARRAY['Ngồi vào máy cáp, lưng thẳng và hai bàn chân đặt phẳng trên sàn.', 'Cầm tay nắm bằng cầm sấp, rộng hơn vai một chút.', 'Ngả người ra sau một chút, kéo tay nắm về phía ngực, siết hai bả vai lại với nhau.', 'Dừng một nhịp ở điểm cao nhất, rồi từ từ thả tay nắm về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('ankle-circles', 'ankle circles', '{CALVES}', '{}', ARRAY['Ngồi trên sàn, hai chân duỗi thẳng về phía trước.', 'Nhấc một chân khỏi sàn và xoay cổ chân theo vòng tròn.', 'Xoay đủ số vòng theo một chiều, rồi đổi sang chiều ngược lại.', 'Lặp lại với chân còn lại.'], '{}', false, false, true),
  ('archer-pull-up', 'archer pull up', '{LATS,BICEPS,FOREARMS}', '{}', ARRAY['Bắt đầu bằng tư thế treo trên xà, tay cầm sấp, rộng hơn vai một chút.', 'Siết cơ lõi, kéo hai bả vai xuống và về phía sau.', 'Khi kéo người lên, gập một tay và đưa khuỷu về sát hông, đồng thời giữ tay còn lại thẳng.', 'Tiếp tục kéo cho tới khi cằm vượt qua xà và tay đang gập gập hết cỡ.', 'Hạ người xuống từ từ, duỗi thẳng tay đang gập và lặp lại bên kia.', 'Luân phiên hai bên sau mỗi lần lặp.'], '{}', false, false, true),
  ('archer-push-up', 'archer push up', '{CHEST,TRICEPS,SHOULDERS,CORE}', '{}', ARRAY['Bắt đầu ở tư thế chống đẩy, hai tay đặt rộng hơn vai một chút.', 'Duỗi thẳng một tay ra sang ngang, song song với sàn.', 'Hạ người bằng cách gập khuỷu tay, giữ lưng thẳng và siết cơ lõi.', 'Đẩy người trở lại tư thế ban đầu.', 'Lặp lại bên kia, duỗi tay đối diện ra sang ngang.', 'Tiếp tục luân phiên hai bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('arm-slingers-hanging-bent-knee-legs', 'arm slingers hanging bent knee legs', '{CORE,SHOULDERS,UPPER_BACK}', '{}', ARRAY['Treo trên xà, hai tay duỗi thẳng và hai đầu gối gập một góc 90 độ.', 'Siết cơ lõi và nâng gối lên về phía ngực, đưa gối càng gần khuỷu tay càng tốt.', 'Từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('arm-slingers-hanging-straight-legs', 'arm slingers hanging straight legs', '{CORE,SHOULDERS,UPPER_BACK}', '{}', ARRAY['Treo trên xà, hai tay duỗi thẳng và hai chân thẳng buông xuống.', 'Siết cơ lõi, nâng hai chân lên trước người cho tới khi song song với sàn.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('arms-apart-circular-toe-touch-male', 'arms apart circular toe touch (male)', '{GLUTES,HAMSTRINGS,QUADS,CALVES}', '{}', ARRAY['Đứng, hai chân rộng bằng vai, hai tay dang ra hai bên.', 'Giữ thẳng hai chân, gập người từ eo và đưa tay phải xuống chạm ngón chân.', 'Khi cúi xuống, đồng thời nâng chân trái thẳng ra phía sau, giữ thăng bằng.', 'Trở về tư thế ban đầu, lặp lại với tay trái chạm ngón chân và nâng chân phải ra sau.', 'Tiếp tục luân phiên hai bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('arms-overhead-full-sit-up-male', 'arms overhead full sit-up (male)', '{CORE,LOWER_BACK}', '{}', ARRAY['Nằm ngửa, gối co, bàn chân đặt phẳng trên sàn.', 'Duỗi thẳng hai tay qua đầu.', 'Siết cơ bụng, từ từ nâng thân trên khỏi sàn, cuộn người về phía trước tới khi thân thẳng đứng.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-chest-dip-kneeling', 'assisted chest dip (kneeling)', '{CHEST,TRICEPS,SHOULDERS}', '{MACHINE}', ARRAY['Chỉnh máy tới độ cao mong muốn và đặt hai đầu gối lên đệm.', 'Nắm tay cầm, lòng bàn tay hướng xuống, hai tay duỗi thẳng.', 'Hạ người bằng cách gập khuỷu tay tới khi cánh tay trên song song với sàn.', 'Dừng một nhịp, rồi đẩy người trở lại tư thế ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-hanging-knee-raise', 'assisted hanging knee raise', '{CORE}', '{MACHINE}', ARRAY['Treo trên xà, hai tay duỗi thẳng, lòng bàn tay hướng ra xa.', 'Siết cơ bụng và nâng đầu gối lên về phía ngực, gập hông và gập gối.', 'Dừng một nhịp ở trên cùng, siết chặt cơ bụng.', 'Từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-hanging-knee-raise-with-throw-down', 'assisted hanging knee raise with throw down', '{CORE,LOWER_BACK}', '{MACHINE}', ARRAY['Treo trên xà, hai tay duỗi thẳng, lòng bàn tay hướng ra xa.', 'Siết cơ bụng và nâng đầu gối lên ngang ngực, giữ hai chân khép lại.', 'Khi đầu gối lên tới ngang ngực, quăng mạnh hai chân xuống dưới, duỗi thẳng hết cỡ.', 'Để chân đung đưa trở lên và lặp lại động tác đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-lying-calves-stretch', 'assisted lying calves stretch', '{CALVES,HAMSTRINGS}', '{MACHINE}', ARRAY['Nằm ngửa, duỗi thẳng hai chân.', 'Gập một gối và đặt bàn chân phẳng trên sàn.', 'Dùng tay hoặc khăn, nhẹ nhàng kéo mũi chân về phía người, cảm nhận căng ở bắp chân.', 'Giữ kéo giãn 20-30 giây.', 'Thả ra và lặp lại với chân còn lại.'], '{}', false, false, true),
  ('assisted-lying-glutes-stretch', 'assisted lying glutes stretch', '{GLUTES,HAMSTRINGS}', '{MACHINE}', ARRAY['Nằm ngửa, duỗi thẳng hai chân.', 'Gập gối phải và đặt mắt cá chân phải lên đùi trái, ngay phía trên đầu gối.', 'Hai tay nắm đùi trái và nhẹ nhàng kéo về phía ngực.', 'Giữ kéo giãn 20-30 giây.', 'Thả ra và lặp lại bên kia.'], '{}', false, false, true),
  ('assisted-lying-gluteus-and-piriformis-stretch', 'assisted lying gluteus and piriformis stretch', '{GLUTES,HAMSTRINGS}', '{MACHINE}', ARRAY['Nằm ngửa, duỗi thẳng hai chân.', 'Gập gối phải và đặt mắt cá chân phải lên đùi trái, ngay phía trên đầu gối.', 'Hai tay nắm đùi trái và nhẹ nhàng kéo về phía ngực.', 'Giữ kéo giãn 20-30 giây.', 'Thả ra và lặp lại bên kia.'], '{}', false, false, true),
  ('assisted-lying-leg-raise-with-lateral-throw-down', 'assisted lying leg raise with lateral throw down', '{CORE}', '{MACHINE}', ARRAY['Nằm ngửa, duỗi thẳng hai chân, hai tay buông bên người.', 'Đặt hai tay dưới mông để đỡ.', 'Siết cơ bụng và nâng hai chân khỏi sàn, giữ thẳng.', 'Giữ hai chân khép lại, hạ sang một bên cho tới khi cách sàn vài cm.', 'Dừng một nhịp, rồi nâng chân trở về tư thế ban đầu.', 'Lặp lại động tác sang bên kia.', 'Tiếp tục luân phiên hai bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-lying-leg-raise-with-throw-down', 'assisted lying leg raise with throw down', '{CORE,QUADS}', '{MACHINE}', ARRAY['Nằm ngửa, duỗi thẳng hai chân, hai tay buông bên người.', 'Đặt hai tay dưới mông để đỡ.', 'Siết cơ lõi và nâng hai chân khỏi sàn, giữ thẳng.', 'Nâng chân cho tới khi vuông góc với sàn.', 'Hạ chân về vị trí ban đầu.', 'Đồng thời quăng hai chân xuống sàn, giữ thẳng.', 'Nâng chân trở lại vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-motion-russian-twist', 'assisted motion russian twist', '{CORE,LOWER_BACK}', '{BALL}', ARRAY['Ngồi trên sàn, gối co và hai bàn chân đặt phẳng trên sàn.', 'Cầm bóng tạ bằng hai tay, đặt trước ngực.', 'Ngả người ra sau một chút, siết cơ bụng và giữ lưng thẳng.', 'Từ từ xoay thân sang phải, đưa bóng tạ về phía bên phải cơ thể.', 'Dừng một nhịp, rồi xoay thân sang trái, đưa bóng tạ về phía bên trái cơ thể.', 'Tiếp tục luân phiên hai bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-parallel-close-grip-pull-up', 'assisted parallel close grip pull-up', '{LATS,BICEPS,FOREARMS}', '{MACHINE}', ARRAY['Chỉnh máy tới mức tải và độ cao mong muốn.', 'Đặt hai tay lên xà song song, cầm hẹp, lòng bàn tay hướng vào nhau.', 'Treo người trên xà, hai tay duỗi thẳng và hai chân không chạm đất.', 'Siết cơ lưng và kéo người lên về phía xà, giữ khuỷu tay sát người.', 'Kéo tới khi cằm vượt qua xà.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-prone-hamstring', 'assisted prone hamstring', '{HAMSTRINGS,GLUTES,LOWER_BACK}', '{MACHINE}', ARRAY['Nằm sấp trên thảm hoặc ghế tập, duỗi thẳng hai chân.', 'Nhờ người khác hoặc dùng dây kháng lực để cố định mắt cá chân.', 'Siết cơ đùi sau và nâng chân về phía mông, giữ gối thẳng.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-prone-lying-quads-stretch', 'assisted prone lying quads stretch', '{QUADS,HAMSTRINGS,GLUTES}', '{MACHINE}', ARRAY['Nằm sấp trên sàn, duỗi thẳng hai chân.', 'Gập gối trái và đưa tay trái ra sau nắm bàn chân hoặc mắt cá chân trái.', 'Nhẹ nhàng kéo bàn chân trái về phía mông, cảm nhận căng ở đùi trước trái.', 'Giữ kéo giãn 20-30 giây, rồi thả ra.', 'Lặp lại với chân phải.'], '{}', false, false, true),
  ('assisted-prone-rectus-femoris-stretch', 'assisted prone rectus femoris stretch', '{CORE,QUADS}', '{MACHINE}', ARRAY['Nằm sấp trên sàn, hai chân duỗi thẳng.', 'Gập gối phải và đưa tay phải ra sau nắm bàn chân hoặc mắt cá chân phải.', 'Nhẹ nhàng kéo bàn chân hoặc mắt cá chân phải về phía mông, cảm nhận căng ở phía trước đùi phải.', 'Giữ kéo giãn 20-30 giây.', 'Thả ra và lặp lại bên kia.'], '{}', false, false, true),
  ('assisted-pull-up', 'assisted pull-up', '{LATS,BICEPS,FOREARMS}', '{MACHINE}', ARRAY['Chỉnh máy tới mức tải và độ cao mong muốn.', 'Nắm tay cầm, cầm sấp, rộng hơn vai một chút.', 'Treo người, hai tay duỗi thẳng và hai chân không chạm đất.', 'Siết cơ lưng và kéo người lên về phía tay cầm, giữ khuỷu tay sát người.', 'Kéo tới khi cằm vượt qua tay cầm.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-seated-pectoralis-major-stretch-with-stability-ball', 'assisted seated pectoralis major stretch with stability ball', '{CHEST,SHOULDERS,TRICEPS}', '{MACHINE}', ARRAY['Ngồi trên bóng tập, hai bàn chân đặt phẳng trên sàn và lưng thẳng.', 'Hai tay cầm bóng tập, duỗi thẳng tay ra phía trước.', 'Từ từ hạ bóng về phía ngực, cảm nhận căng ở cơ ngực.', 'Giữ tư thế vài giây, rồi từ từ trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-side-lying-adductor-stretch', 'assisted side lying adductor stretch', '{ADDUCTORS,HAMSTRINGS,GLUTES}', '{MACHINE}', ARRAY['Nằm nghiêng, hai chân duỗi thẳng và xếp chồng lên nhau.', 'Gập nhẹ chân dưới để giữ thăng bằng.', 'Đặt bàn chân trên cùng lên một chỗ vững chắc, như ghế dài hoặc bậc thang.', 'Giữ chân trên thẳng, từ từ hạ xuống về phía sàn, cảm nhận căng ở đùi trong.', 'Giữ kéo giãn 20-30 giây.', 'Trở về tư thế ban đầu và lặp lại bên kia.'], '{}', false, false, true),
  ('assisted-sit-up', 'assisted sit-up', '{CORE}', '{MACHINE}', ARRAY['Ngồi trên mép ghế dài hoặc nhờ người giữ chân xuống.', 'Nằm ngửa, gối co và hai bàn chân đặt phẳng trên sàn.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết cơ bụng, từ từ nâng thân trên khỏi sàn, cuộn người về phía trước tới khi thân tạo góc 45 độ.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-standing-chin-up', 'assisted standing chin-up', '{LATS,BICEPS,FOREARMS}', '{MACHINE}', ARRAY['Chỉnh máy tới mức hỗ trợ mong muốn.', 'Đứng lên bệ chân, nắm tay cầm cầm sấp, rộng hơn vai một chút.', 'Giữ ngực ưỡn, vai ra sau, siết cơ lõi và hơi gập gối.', 'Kéo người lên bằng cách gập khuỷu tay và kéo khuỷu xuống về phía hông.', 'Tiếp tục kéo tới khi cằm vượt qua xà.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-standing-pull-up', 'assisted standing pull-up', '{LATS,BICEPS,FOREARMS}', '{MACHINE}', ARRAY['Chỉnh máy tới mức tải và độ cao mong muốn.', 'Đứng quay mặt vào máy, hai chân rộng bằng vai.', 'Nắm tay cầm cầm sấp, rộng hơn vai một chút.', 'Siết cơ xô và tay trước, kéo người lên về phía tay cầm.', 'Dừng một nhịp ở trên cùng, siết cơ lưng.', 'Từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
