  ('assisted-triceps-dip-kneeling', 'assisted triceps dip (kneeling)', '{TRICEPS,CHEST,SHOULDERS}', '{MACHINE}', ARRAY['Chỉnh máy tới mức tải và độ cao mong muốn.', 'Quỳ lên đệm, quay mặt vào máy, hai tay nắm tay cầm.', 'Hạ người bằng cách gập khuỷu tay, giữ lưng thẳng và sát máy.', 'Dừng một nhịp ở dưới cùng, rồi đẩy người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('assisted-wide-grip-chest-dip-kneeling', 'assisted wide-grip chest dip (kneeling)', '{CHEST,TRICEPS,SHOULDERS}', '{MACHINE}', ARRAY['Chỉnh máy tới độ cao mong muốn và đặt hai đầu gối lên đệm.', 'Nắm tay cầm cầm rộng và giữ khuỷu tay hơi gập.', 'Hạ người bằng cách gập khuỷu tay tới khi cánh tay trên song song với sàn.', 'Đẩy người về vị trí ban đầu bằng cách duỗi thẳng tay.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('astride-jumps-male', 'astride jumps (male)', '{CARDIO,QUADS,HAMSTRINGS,CALVES}', '{}', ARRAY['Đứng, hai chân rộng bằng vai.', 'Gập gối và hạ người xuống tư thế squat.', 'Bật nhảy mạnh lên trên, duỗi thẳng chân và tay.', 'Trên không, dang rộng hai chân và đưa tay ra hai bên.', 'Tiếp đất nhẹ với hai chân rộng bằng vai, gập gối để giảm chấn.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('back-and-forth-step', 'back and forth step', '{CARDIO,QUADS,HAMSTRINGS,GLUTES,CALVES}', '{}', ARRAY['Đứng, hai chân rộng bằng vai.', 'Bước chân phải về phía trước, gập gối và hạ người vào tư thế lunge.', 'Đẩy chân phải và bước lùi về vị trí ban đầu.', 'Lặp lại động tác với chân trái, luân phiên hai chân sau mỗi bước.', 'Tiếp tục bước tới lui, giữ nhịp đều.', 'Lặp lại đủ thời gian hoặc số lần mong muốn.'], '{}', false, false, true),
  ('back-extension-on-exercise-ball', 'back extension on exercise ball', '{LOWER_BACK,GLUTES,HAMSTRINGS}', '{BALL}', ARRAY['Đặt bóng tập trên sàn, nằm sấp lên bóng, hông tựa lên bóng, hai chân tựa vào tường hoặc vật cố định khác.', 'Đặt hai tay sau đầu hoặc khoanh trước ngực.', 'Siết bụng, từ từ nâng thân trên khỏi bóng, duỗi lưng đến khi cơ thể thành một đường thẳng từ đầu tới gót chân.', 'Dừng một chút ở trên cùng, rồi từ từ hạ thân trên về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('back-lever', 'back lever', '{UPPER_BACK,BICEPS,FOREARMS,CORE}', '{}', ARRAY['Bắt đầu bằng cách treo trên xà đơn, cầm sấp, tay rộng hơn vai một chút.', 'Siết bụng, kéo hai bả vai xuống và ra sau.', 'Co gối, kéo sát về phía ngực.', 'Từ từ nâng hai chân lên, giữ thẳng chân, đến khi thân song song với sàn.', 'Giữ tư thế này vài giây, rồi từ từ hạ hai chân về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('back-pec-stretch', 'back pec stretch', '{LATS,SHOULDERS,CHEST}', '{}', ARRAY['Đứng thẳng, hai chân rộng bằng vai.', 'Duỗi thẳng hai tay ra trước, song song với sàn.', 'Khoanh tay trước thân, tay phải đè lên tay trái.', 'Đan ngón tay và xoay lòng bàn tay ra xa thân.', 'Từ từ nâng hai tay lên và ra xa thân, cảm nhận căng ở lưng và ngực.', 'Giữ tư thế căng 15-30 giây, rồi thả ra.', 'Lặp lại ở bên đối diện.'], '{}', false, false, true),
  ('backward-jump', 'backward jump', '{QUADS,HAMSTRINGS,GLUTES,CALVES}', '{}', ARRAY['Đứng, hai chân rộng bằng vai.', 'Hơi khuỵu gối, nhảy lùi về sau, đạp bằng cả hai chân.', 'Tiếp đất nhẹ bằng mũi bàn chân, khuỵu gối để giảm lực va đập.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('balance-board', 'balance board', '{QUADS,CALVES,HAMSTRINGS,GLUTES}', '{}', ARRAY['Đặt bàn thăng bằng trên mặt phẳng.', 'Bước một chân lên bàn thăng bằng, đảm bảo đứng giữa bàn.', 'Từ từ dồn trọng lượng lên chân đang đứng trên bàn, giữ cơ bụng siết.', 'Giữ thăng bằng và ổn định khi giữ tư thế trong khoảng thời gian mong muốn.', 'Lặp lại bài tập với chân còn lại.'], '{}', false, false, true),
