  ('band-assisted-pull-up', 'band assisted pull-up', '{LATS,BICEPS,FOREARMS}', '{BAND}', ARRAY['Gắn dây vào xà đơn hoặc điểm neo chắc chắn.', 'Bước vào dây, nắm xà với lòng bàn tay hướng ra xa người, tay rộng hơn vai một chút.', 'Treo người, duỗi thẳng tay, siết bụng, giữ vai xuống và ra sau.', 'Kéo người lên về phía xà bằng cách siết hai bả vai vào nhau và đưa khuỷu tay xuống về phía hông.', 'Tiếp tục kéo đến khi cằm qua xà, rồi từ từ hạ người về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('band-assisted-wheel-rollerout', 'band assisted wheel rollerout', '{CORE,LOWER_BACK}', '{BAND}', ARRAY['Quỳ trên sàn, hai tay cầm tay cầm của dây, lòng bàn tay hướng xuống.', 'Đặt dây xuống sàn trước mặt, đặt hai tay rộng bằng vai.', 'Siết bụng, từ từ lăn bánh xe về phía trước, duỗi cơ thể ra xa nhất có thể mà vẫn kiểm soát được.', 'Dừng một chút ở điểm xa nhất, rồi từ từ lăn bánh xe về phía đầu gối để trở về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
