  ('band-straight-back-stiff-leg-deadlift', 'band straight back stiff leg deadlift', '{GLUTES,HAMSTRINGS,LOWER_BACK}', '{BAND}', ARRAY['Đứng, hai chân rộng bằng vai, quấn dây quanh đùi trên.', 'Cầm dây bằng hai tay trước đùi, lòng bàn tay hướng vào thân.', 'Giữ lưng thẳng và gối hơi chùng, gập hông và hạ dây về phía sàn.', 'Cảm nhận căng ở gân kheo khi hạ dây.', 'Siết mông và gân kheo để nâng người về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('band-straight-leg-deadlift', 'band straight leg deadlift', '{LOWER_BACK,HAMSTRINGS,GLUTES}', '{BAND}', ARRAY['Đứng, hai chân rộng bằng vai, quấn dây quanh bàn chân.', 'Cầm dây bằng hai tay, lòng bàn tay hướng vào thân, giữ tay thẳng.', 'Siết bụng và giữ đầu gối hơi gập.', 'Từ từ gập hông cúi người về trước, giữ lưng thẳng và ngực ngẩng cao.', 'Hạ dây về phía sàn trong khi giữ chân thẳng.', 'Dừng một chút ở đáy, rồi siết mông và gân kheo để trở về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('band-twisting-overhead-press', 'band twisting overhead press', '{SHOULDERS,TRICEPS,UPPER_BACK}', '{BAND}', ARRAY['Đứng, hai chân rộng bằng vai, đặt dây dưới chân.', 'Cầm tay cầm dây ngang vai, lòng bàn tay hướng về phía trước.', 'Siết bụng và đẩy dây qua đầu, duỗi thẳng hết hai tay.', 'Khi đẩy, xoay thân về một bên, giữ hông ổn định.', 'Dừng một chút ở trên cùng, rồi trở về vị trí xuất phát.', 'Lặp lại động tác đẩy và xoay sang bên còn lại.', 'Tiếp tục đổi bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('band-two-legs-calf-raise-band-under-both-legs-v-2', 'band two legs calf raise - (band under both legs) v. 2', '{CALVES}', '{BAND}', ARRAY['Đứng, hai chân rộng bằng vai, đặt dây kháng lực dưới cả hai chân.', 'Cầm hai đầu dây bằng tay để giữ thăng bằng.', 'Nhấc gót chân lên khỏi sàn càng cao càng tốt, dùng cơ bắp chân.', 'Dừng một chút ở trên cùng, rồi từ từ hạ gót chân về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('band-underhand-pulldown', 'band underhand pulldown', '{LATS,BICEPS,FOREARMS}', '{BAND}', ARRAY['Gắn dây vào điểm neo cao, như xà đơn hoặc dầm chắc chắn.', 'Đứng đối diện điểm neo, hai chân rộng bằng vai.', 'Cầm dây bằng cách cầm ngửa, hai tay rộng hơn vai một chút.', 'Duỗi thẳng hết hai tay phía trên đầu, giữ khuỷu tay hơi chùng.', 'Siết cơ xô và kéo dây xuống về phía ngực, siết hai bả vai vào nhau.', 'Dừng một chút ở cuối động tác, rồi từ từ nới lực và trở về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('band-v-up', 'band v-up', '{CORE}', '{BAND}', ARRAY['Nằm ngửa, chân duỗi thẳng, hai tay duỗi qua đầu, cầm dây.', 'Siết bụng, nâng đồng thời chân và thân trên, đưa tay về phía ngón chân.', 'Dừng một chút ở trên cùng, rồi từ từ hạ chân và thân trên về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('band-vertical-pallof-press', 'band vertical pallof press', '{CORE,GLUTES}', '{BAND}', ARRAY['Đứng, hai chân rộng bằng vai, quấn dây quanh vật cố định ngang ngực.', 'Cầm dây bằng hai tay và bước ra xa điểm neo để tạo lực căng cho dây.', 'Đứng vuông góc với điểm neo, để cạnh người hướng về phía dây.', 'Duỗi thẳng hai tay ra trước, giữ tay ngang ngực.', 'Siết bụng và đẩy dây ra xa ngực, duỗi thẳng hết hai tay.', 'Giữ tư thế vài giây, rồi từ từ kéo dây về ngực.', 'Lặp lại đủ số lần mong muốn, rồi đổi bên.'], '{}', false, false, true),
  ('band-wrist-curl', 'band wrist curl', '{FOREARMS,BICEPS,TRICEPS}', '{BAND}', ARRAY['Ngồi trên ghế dài hoặc ghế, hai chân đặt phẳng trên sàn.', 'Cầm dây bằng hai tay, lòng bàn tay hướng lên, đặt cẳng tay lên đùi.', 'Từ từ cuốn cổ tay lên trên, siết cẳng tay.', 'Dừng một chút ở trên cùng, rồi từ từ hạ cổ tay về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('band-y-raise', 'band y-raise', '{SHOULDERS,UPPER_BACK}', '{BAND}', ARRAY['Đứng, hai chân rộng bằng vai, cầm dây trước đùi với lòng bàn tay hướng vào trong.', 'Giữ tay thẳng và nâng tay lên, dang ra hai bên, tạo thành hình chữ Y với cơ thể.', 'Siết hai bả vai vào nhau ở trên cùng.', 'Từ từ hạ tay về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
