  ('barbell-side-split-squat', 'barbell side split squat', '{QUADS,GLUTES,HAMSTRINGS,CALVES}', '{BARBELL_RACK}', ARRAY['Đứng, hai chân rộng hơn vai một chút, mũi chân hướng hơi ra ngoài.', 'Cầm tạ đòn trên lưng trên, tựa trên cơ cầu vai.', 'Siết bụng và giữ ngực ngẩng cao khi hạ người xuống tư thế squat, gập hông và gối.', 'Khi hạ xuống, đẩy đầu gối ra hai bên và giữ trọng lượng dồn vào gót chân.', 'Hạ đến khi đùi song song với sàn, rồi đẩy qua gót chân để trở về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('barbell-side-split-squat-v-2', 'barbell side split squat v. 2', '{QUADS,GLUTES,HAMSTRINGS,CALVES}', '{BARBELL_RACK}', ARRAY['Đứng, hai chân rộng hơn vai một chút, mũi chân hướng hơi ra ngoài.', 'Cầm tạ đòn trên lưng trên, tựa trên vai.', 'Bước dài sang ngang bằng chân phải, giữ chân trái đứng yên.', 'Gập gối phải và hạ người xuống tư thế squat, giữ ngực ngẩng cao và lưng thẳng.', 'Đẩy qua gót chân phải để trở về vị trí xuất phát.', 'Lặp lại ở bên còn lại, bước sang ngang bằng chân trái.', 'Tiếp tục đổi bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('barbell-single-leg-deadlift', 'barbell single leg deadlift', '{GLUTES,HAMSTRINGS,LOWER_BACK}', '{BARBELL_RACK}', ARRAY['Đứng, hai chân rộng bằng hông, cầm tạ đòn trước đùi bằng cách cầm sấp.', 'Chuyển trọng lượng sang chân trái và nhấc nhẹ chân phải khỏi sàn.', 'Gập hông cúi người về trước, giữ lưng thẳng và duỗi chân phải ra sau để giữ thăng bằng.', 'Hạ tạ về phía sàn, giữ tạ sát người và chân trái hơi gập.', 'Dừng một chút ở đáy, rồi siết mông và gân kheo để nâng thân trên về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn, rồi đổi bên.'], '{}', false, false, true),
  ('barbell-single-leg-split-squat', 'barbell single leg split squat', '{QUADS,GLUTES,HAMSTRINGS,CALVES}', '{BARBELL_RACK}', ARRAY['Đứng, hai chân rộng bằng vai, tạ đòn đặt trên lưng trên.', 'Bước dài một chân ra trước, giữ thân người thẳng đứng.', 'Hạ người bằng cách gập đầu gối và hông trước, giữ chân sau thẳng.', 'Tiếp tục hạ đến khi đùi trước song song với sàn.', 'Dừng một chút, rồi đẩy qua gót chân trước để trở về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn, rồi đổi chân.'], '{}', false, false, true),
  ('barbell-sitted-alternate-leg-raise', 'barbell sitted alternate leg raise', '{CORE}', '{BARBELL_RACK}', ARRAY['Ngồi trên ghế, lưng thẳng và đặt tạ đòn ngang đùi.', 'Giữ chân duỗi thẳng, nhấc một chân lên cao hết mức có thể, chân còn lại đặt trên sàn.', 'Hạ chân vừa nâng xuống và lặp lại với chân còn lại.', 'Tiếp tục đổi chân xen kẽ đủ số lần mong muốn.'], '{}', false, false, true),
  ('barbell-sitted-alternate-leg-raise-female', 'barbell sitted alternate leg raise (female)', '{CORE,QUADS}', '{BARBELL_RACK}', ARRAY['Ngồi trên ghế, lưng thẳng và đặt tạ đòn ngang đùi.', 'Đặt hai tay lên hai bên ghế để giữ thăng bằng.', 'Giữ chân duỗi thẳng, nhấc một chân lên cao hết mức có thể và giữ song song với sàn.', 'Hạ chân xuống và lặp lại với chân còn lại.', 'Tiếp tục đổi chân xen kẽ đủ số lần mong muốn.'], '{}', false, false, true),
  ('barbell-skier', 'barbell skier', '{SHOULDERS,TRICEPS,CORE}', '{BARBELL_RACK}', ARRAY['Đứng, hai chân rộng bằng vai, cầm tạ đòn trước đùi bằng cách cầm sấp.', 'Hơi khuỵu gối và gập hông cúi người về trước, giữ lưng thẳng và ngực ngẩng cao.', 'Đồng thời nâng tạ lên về phía vai và nhảy nhẹ khỏi sàn.', 'Khi lên đến đỉnh động tác, nhanh chóng đảo chiều và hạ tạ về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('barbell-speed-squat', 'barbell speed squat', '{GLUTES,QUADS,HAMSTRINGS,CALVES}', '{BARBELL_RACK}', ARRAY['Đứng, hai chân rộng bằng vai, mũi chân hơi xoay ra ngoài.', 'Đặt tạ đòn trên lưng trên, tựa trên cơ cầu vai hoặc vai sau.', 'Siết bụng và giữ ngực ngẩng cao khi hạ hông ra sau và xuống dưới, như đang ngồi xuống ghế.', 'Hạ đến khi đùi song song với sàn, hoặc thấp nhất mà bạn thoải mái.', 'Đẩy qua gót chân để đứng dậy, siết mông ở trên cùng.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('barbell-split-squat-v-2', 'barbell split squat v. 2', '{QUADS,GLUTES,HAMSTRINGS,CALVES}', '{BARBELL_RACK}', ARRAY['Bắt đầu bằng cách đứng, hai chân rộng bằng vai, tạ đòn đặt trên lưng trên.', 'Bước dài chân phải ra trước, giữ thân người thẳng đứng.', 'Hạ người bằng cách gập gối và hông cho đến khi đùi phải song song với sàn.', 'Dừng một chút, rồi đẩy qua gót chân phải để trở về vị trí xuất phát.', 'Lặp lại với chân trái bước ra trước đủ số lần mong muốn.'], '{}', false, false, true),
  ('barbell-squat-on-knees', 'barbell squat (on knees)', '{QUADS,GLUTES,HAMSTRINGS,CALVES}', '{BARBELL_RACK}', ARRAY['Bắt đầu bằng cách quỳ trên sàn, hai đầu gối rộng bằng hông và mũi chân hướng về phía trước.', 'Đặt tạ đòn lên vai, cầm tạ bằng cách cầm sấp, hai tay rộng hơn vai một chút.', 'Siết bụng và giữ ngực ngẩng cao, từ từ hạ người bằng cách gập gối, giữ lưng thẳng.', 'Tiếp tục hạ đến khi đùi song song với sàn, hoặc thấp nhất mà bạn thoải mái.', 'Dừng một chút ở đáy, rồi đẩy qua gót chân để trở về vị trí xuất phát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true)
ON CONFLICT (slug) DO NOTHING;

