  ('cable-standing-row-v-bar', 'cable standing row (v-bar)', '{UPPER_BACK,BICEPS,SHOULDERS}', '{CABLE}', ARRAY['Đứng đối diện máy cáp, chân rộng bằng vai.', 'Cầm tay cầm chữ V bằng kiểu cầm sấp, lòng bàn tay hướng xuống.', 'Giữ lưng thẳng và siết bụng.', 'Kéo tay cầm chữ V về phía người, siết xương bả vai lại.', 'Dừng một nhịp ở đỉnh động tác, rồi từ từ nhả lực và về tư thế ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-standing-shoulder-external-rotation', 'cable standing shoulder external rotation', '{SHOULDERS,UPPER_BACK}', '{CABLE}', ARRAY['Đứng chân rộng bằng vai, gối hơi chùng.', 'Cầm tay cầm máy cáp với tay duỗi thẳng ra trước, song song với sàn.', 'Giữ khuỷu hơi gập và kéo xương bả vai ra sau.', 'Từ từ xoay cánh tay ra ngoài, xa thân người, giữ khuỷu ở vị trí cũ.', 'Dừng một nhịp ở cuối động tác, rồi từ từ trở về tư thế ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-standing-twist-row-v-bar', 'cable standing twist row (v-bar)', '{UPPER_BACK,BICEPS,SHOULDERS}', '{CABLE}', ARRAY['Gắn tay cầm chữ V vào máy cáp ngang ngực.', 'Đứng đối diện máy cáp, chân rộng bằng vai.', 'Cầm tay cầm chữ V bằng kiểu cầm sấp, lòng bàn tay hướng xuống.', 'Lùi một bước để dây cáp căng.', 'Giữ lưng thẳng và siết bụng suốt bài.', 'Kéo tay cầm chữ V về phía thân người bằng cách rụt xương bả vai và gập khuỷu.', 'Khi kéo, xoay thân người sang một bên, siết xương bả vai lại.', 'Dừng một nhịp ở trên cùng, cảm nhận co cơ ở lưng trên.', 'Từ từ nhả lực và trở về tư thế ban đầu, xoay thân người trở lại.', 'Lặp lại đủ số lần mong muốn, đổi chiều xoay sau mỗi lần.'], '{}', false, false, true),
  ('cable-standing-up-straight-crossovers', 'cable standing up straight crossovers', '{CHEST,SHOULDERS,TRICEPS}', '{CABLE}', ARRAY['Đứng giữa máy cáp, chân rộng bằng vai.', 'Cầm tay cầm dây cáp với lòng bàn tay hướng xuống và hai tay dang thẳng sang hai bên.', 'Giữ tay thẳng, đưa hai tay về trước người và bắt chéo qua nhau.', 'Dừng một nhịp, rồi từ từ trở về tư thế ban đầu, giữ tay duỗi thẳng.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO exercises (slug, name_en, muscle_groups, equipment, steps_vi, mistakes_vi, analyzable, is_active, is_draft) VALUES
  ('cable-straight-arm-pulldown', 'cable straight arm pulldown', '{LATS,SHOULDERS,BICEPS}', '{CABLE}', ARRAY['Gắn thanh thẳng vào ròng rọc cao của máy cáp.', 'Đứng đối diện máy, chân rộng bằng vai.', 'Cầm thanh bằng kiểu cầm sấp, giữ tay thẳng.', 'Siết cơ xô và kéo thanh xuống về phía đùi, giữ tay thẳng suốt động tác.', 'Dừng một nhịp ở dưới cùng, rồi từ từ đưa thanh về tư thế ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-straight-arm-pulldown-with-rope', 'cable straight arm pulldown (with rope)', '{LATS,BICEPS,FOREARMS}', '{CABLE}', ARRAY['Gắn dây thừng vào máy cáp ở vị trí cao nhất.', 'Đứng đối diện máy, chân rộng bằng vai.', 'Cầm dây bằng hai tay, lòng bàn tay hướng xuống.', 'Duỗi thẳng hai tay ra trước, giữ khuỷu hơi gập.', 'Siết cơ xô và từ từ kéo dây xuống về phía đùi, giữ tay thẳng.', 'Dừng một nhịp ở dưới cùng, rồi từ từ nhả lực và về tư thế ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-straight-back-seated-row', 'cable straight back seated row', '{UPPER_BACK,BICEPS,FOREARMS,SHOULDERS}', '{CABLE}', ARRAY['Ngồi lên máy kéo cáp, hai chân đặt phẳng trên bệ chân và hơi khuỵu gối.', 'Nắm tay cầm cáp kiểu cầm sấp, lòng bàn tay hướng xuống.', 'Giữ lưng thẳng và hơi nghiêng người về phía trước từ hông.', 'Kéo tay cầm về phía thân, siết hai bả vai lại với nhau.', 'Dừng một nhịp ở điểm cuối động tác, rồi từ từ thả tay cầm về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-supine-reverse-fly', 'cable supine reverse fly', '{SHOULDERS,UPPER_BACK}', '{CABLE}', ARRAY['Gắn tay cầm chữ D vào máy cáp ròng rọc thấp rồi nằm sấp trên ghế phẳng.', 'Nắm tay cầm chữ D bằng mỗi tay, lòng bàn tay hướng xuống, duỗi thẳng tay ra phía trước.', 'Giữ tay thẳng, nâng tay sang hai bên cho đến khi song song với sàn.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tay về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-thibaudeau-kayak-row', 'cable thibaudeau kayak row', '{LATS,BICEPS,UPPER_BACK,SHOULDERS}', '{CABLE}', ARRAY['Gắn tay cầm cáp vào ròng rọc thấp, ngồi quay mặt về máy và đặt hai chân phẳng trên sàn.', 'Nắm tay cầm bằng tay phải, duỗi thẳng hết cỡ tay và giữ khuỷu hơi cong.', 'Nghiêng người về phía trước từ hông, giữ lưng thẳng và siết cơ bụng.', 'Kéo tay cầm về phía thân bằng cách rụt bả vai và gập khuỷu, giữ tay sát người.', 'Siết cơ lưng ở điểm cuối động tác, rồi từ từ trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, sau đó đổi bên và tập bằng tay trái.'], '{}', false, false, true),
  ('cable-triceps-pushdown-v-bar', 'cable triceps pushdown (v-bar)', '{TRICEPS,FOREARMS}', '{CABLE}', ARRAY['Gắn tay cầm chữ V vào máy cáp ở độ cao cao nhất.', 'Đứng quay mặt về máy cáp, hai chân rộng bằng vai.', 'Nắm tay cầm chữ V kiểu cầm sấp, lòng bàn tay hướng xuống, hai tay rộng bằng vai.', 'Giữ khuỷu sát hai bên hông và cánh tay trên đứng yên suốt động tác.', 'Siết cơ tay sau, thở ra khi đẩy tay cầm xuống cho đến khi tay duỗi thẳng hết cỡ.', 'Dừng một nhịp ở đáy động tác, siết cơ tay sau.', 'Hít vào khi từ từ đưa tay cầm về vị trí ban đầu, giữ kiểm soát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-triceps-pushdown-v-bar-with-arm-blaster', 'cable triceps pushdown (v-bar) (with arm blaster)', '{TRICEPS,FOREARMS}', '{CABLE}', ARRAY['Gắn tay cầm chữ V vào máy cáp ở độ cao cao nhất.', 'Đứng quay mặt về máy cáp, hai chân rộng bằng vai.', 'Nắm tay cầm chữ V kiểu cầm sấp, lòng bàn tay hướng xuống, hai tay rộng bằng vai.', 'Giữ khuỷu sát hai bên hông và cánh tay trên đứng yên suốt động tác.', 'Siết cơ tay sau, thở ra khi đẩy tay cầm xuống cho đến khi tay duỗi thẳng hết cỡ.', 'Dừng một nhịp ở đáy động tác, siết cơ tay sau.', 'Hít vào khi từ từ đưa tay cầm về vị trí ban đầu, giữ kiểm soát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-tuck-reverse-crunch', 'cable tuck reverse crunch', '{CORE}', '{CABLE}', ARRAY['Gắn cáp vào ròng rọc thấp rồi nằm ngửa trên thảm.', 'Nắm cáp bằng hai tay và duỗi thẳng tay lên phía trên ngực.', 'Gập gối và nâng chân lên, đưa đầu gối về phía ngực.', 'Đồng thời cuộn xương chậu lên về phía ngực, nâng hông khỏi sàn.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ chân và hông về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-twist', 'cable twist', '{CORE}', '{CABLE}', ARRAY['Đứng hai chân rộng bằng vai, quay mặt về máy cáp.', 'Cầm tay cầm cáp bằng hai tay trước ngực, giữ tay hơi cong.', 'Siết cơ bụng và xoay thân sang phải, kéo cáp qua người.', 'Dừng một nhịp ở cuối động tác, cảm nhận cơ bụng và cơ chéo bụng co lại.', 'Từ từ trở về vị trí ban đầu, cưỡng lại lực kéo của cáp.', 'Lặp lại động tác sang bên trái.', 'Tiếp tục xen kẽ hai bên cho đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-twist-up-down', 'cable twist (up-down)', '{CORE,LOWER_BACK}', '{CABLE}', ARRAY['Đứng hai chân rộng bằng vai, quay mặt về máy cáp.', 'Cầm tay cầm cáp bằng hai tay trước ngực, giữ tay hơi cong.', 'Siết cơ bụng và từ từ xoay thân sang một bên, giữ hông và chân ổn định.', 'Dừng một nhịp ở cuối vòng xoay, rồi từ từ trở về vị trí ban đầu.', 'Lặp lại vòng xoay sang bên đối diện.', 'Tiếp tục xen kẽ hai bên cho đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-twisting-pull', 'cable twisting pull', '{LATS,SHOULDERS,BICEPS}', '{CABLE}', ARRAY['Gắn tay cầm cáp vào ròng rọc thấp và đứng quay mặt về máy.', 'Nắm tay cầm bằng tay trái, bước ra xa máy và duỗi thẳng hết cỡ tay.', 'Đặt hai chân rộng bằng vai, hơi khuỵu gối.', 'Giữ lưng thẳng và siết cơ bụng suốt động tác.', 'Kéo tay cầm về phía thân, xoay thân sang phải khi kéo.', 'Siết cơ lưng ở cuối động tác.', 'Từ từ trở về vị trí ban đầu, giữ lực căng trên cáp.', 'Lặp lại đủ số lần mong muốn, rồi đổi bên và tập bằng tay phải.'], '{}', false, false, true),
  ('cable-two-arm-curl-on-incline-bench', 'cable two arm curl on incline bench', '{BICEPS,FOREARMS}', '{CABLE,BENCH}', ARRAY['Ngồi lên ghế dốc lên, lưng tựa vào đệm và hai chân đặt phẳng trên sàn.', 'Nắm tay cầm cáp kiểu cầm ngửa, lòng bàn tay hướng lên, hai tay duỗi thẳng.', 'Giữ cánh tay trên đứng yên, thở ra và cuốn tay cầm về phía vai, co cơ tay trước.', 'Dừng một nhịp ở trên cùng, siết cơ tay trước.', 'Hít vào và từ từ hạ tay cầm về vị trí ban đầu, duỗi thẳng hết hai tay.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-two-arm-tricep-kickback', 'cable two arm tricep kickback', '{TRICEPS,SHOULDERS}', '{CABLE}', ARRAY['Đứng hai chân rộng bằng vai, hơi khuỵu gối.', 'Cầm tay cầm cáp bằng mỗi tay, lòng bàn tay hướng vào trong và khuỷu gập 90 độ.', 'Giữ cánh tay trên đứng yên, duỗi cẳng tay ra phía sau cho đến khi tay duỗi thẳng hết cỡ.', 'Dừng một nhịp, rồi từ từ trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
