  ('cable-upper-chest-crossovers', 'cable upper chest crossovers', '{CHEST,SHOULDERS,TRICEPS}', '{CABLE}', ARRAY['Gắn tay cầm vào cáp ở ngang ngực.', 'Đứng giữa máy cáp, một chân hơi đặt trước chân kia.', 'Nắm tay cầm, lòng bàn tay hướng xuống, hai tay dang ngang ra hai bên.', 'Giữ khuỷu hơi cong và siết cơ bụng.', 'Kéo hai cáp lại trước ngực, bắt chéo nhau.', 'Siết cơ ngực ở điểm cao nhất của động tác.', 'Từ từ thả cáp về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-upper-row', 'cable upper row', '{UPPER_BACK,BICEPS,SHOULDERS}', '{CABLE}', ARRAY['Gắn thanh thẳng vào máy cáp ở ngang ngực.', 'Đứng quay mặt về máy, hai chân rộng bằng vai.', 'Nắm thanh kiểu cầm sấp, hai tay rộng hơn vai một chút.', 'Giữ lưng thẳng và siết cơ bụng.', 'Kéo thanh về phía ngực trên, siết hai bả vai lại với nhau.', 'Dừng một nhịp ở điểm cao nhất của động tác.', 'Từ từ thả thanh về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-upright-row', 'cable upright row', '{SHOULDERS,UPPER_BACK,BICEPS}', '{CABLE}', ARRAY['Đứng hai chân rộng bằng vai, hơi khuỵu gối, nắm tay gắn cáp kiểu cầm sấp.', 'Giữ lưng thẳng và siết cơ bụng suốt động tác.', 'Kéo tay gắn cáp thẳng lên về phía cằm, dẫn đầu bằng khuỷu tay.', 'Dừng một nhịp ở trên cùng, siết hai bả vai lại với nhau.', 'Từ từ hạ tay gắn cáp về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-wide-grip-rear-pulldown-behind-neck', 'cable wide grip rear pulldown behind neck', '{LATS,BICEPS,UPPER_BACK,SHOULDERS}', '{CABLE}', ARRAY['Chỉnh máy cáp sao cho thanh kéo ở độ cao trên đầu.', 'Ngồi xuống ghế, nắm thanh kéo kiểu cầm sấp, tay rộng.', 'Giữ lưng thẳng, ngực ưỡn và ngả người ra sau một chút.', 'Kéo thanh xuống về phía ngực trên, siết hai bả vai lại với nhau.', 'Dừng một nhịp ở đáy động tác, rồi từ từ thả thanh lên vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('cable-wrist-curl', 'cable wrist curl', '{FOREARMS,BICEPS}', '{CABLE}', ARRAY['Gắn thanh thẳng vào máy cáp ròng rọc thấp.', 'Đứng quay mặt về máy, hai chân rộng bằng vai.', 'Nắm thanh kiểu cầm ngửa, lòng bàn tay hướng lên, hai tay rộng bằng vai.', 'Đặt cẳng tay lên ghế hoặc đệm, cổ tay thõng ra khỏi mép.', 'Giữ cẳng tay đứng yên, thở ra và cuốn cổ tay lên cao hết mức.', 'Dừng một nhịp ở trên cùng, rồi hít vào và từ từ hạ thanh về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
