  ('deep-push-up', 'deep push up', '{CHEST,TRICEPS,SHOULDERS}', '{DUMBBELL}', ARRAY['Bắt đầu ở tư thế plank cao, hai tay rộng hơn vai một chút và thân người thẳng một đường.', 'Hạ ngực xuống sàn bằng cách gập khuỷu, giữ khuỷu sát thân.', 'Đẩy qua lòng bàn tay để duỗi tay và trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('diamond-push-up', 'diamond push-up', '{TRICEPS,CHEST,SHOULDERS}', '{}', ARRAY['Bắt đầu ở tư thế plank cao, hai tay đặt gần nhau, ngón cái và ngón trỏ tạo thành hình kim cương.', 'Giữ thân thẳng một đường từ đầu đến chân, siết core và mông.', 'Hạ ngực về phía hình kim cương tạo bởi hai tay, giữ khuỷu sát thân.', 'Dừng một nhịp ở đáy động tác, rồi đẩy người trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('donkey-calf-raise', 'donkey calf raise', '{CALVES,HAMSTRINGS,GLUTES}', '{}', ARRAY['Đứng với mũi chân đặt trên bề mặt cao, như bậc thang hoặc khối gỗ.', 'Đặt hai tay lên điểm tựa chắc chắn, như tường hoặc lan can, để giữ thăng bằng.', 'Nhấc gót chân lên cao hết mức, dồn trọng lượng cơ thể lên đầu bàn chân.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ gót chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('drop-push-up', 'drop push up', '{CHEST,TRICEPS,SHOULDERS}', '{}', ARRAY['Bắt đầu ở tư thế plank cao, hai tay rộng hơn vai một chút.', 'Hạ ngực xuống sàn, giữ khuỷu sát thân.', 'Khi ngực vừa cách sàn một chút, nhanh chóng thả hai gối xuống sàn.', 'Đẩy người trở về vị trí ban đầu bằng cách duỗi thẳng tay.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('dumbbell-alternate-biceps-curl', 'dumbbell alternate biceps curl', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Đứng thẳng, cầm tạ đơn mỗi tay, lòng bàn tay hướng về phía trước và tay duỗi thẳng.', 'Giữ cánh tay trên đứng yên, thở ra và cuốn tạ trong khi co cơ tay trước.', 'Tiếp tục nâng tạ đến khi cơ tay trước co hết mức và tạ ngang vai.', 'Giữ tư thế co một nhịp, siết cơ tay trước.', 'Hít vào và từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, luân phiên hai tay.'], '{}', false, false, true),
  ('dumbbell-alternate-biceps-curl-with-arm-blaster', 'dumbbell alternate biceps curl (with arm blaster)', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Đứng thẳng, hai chân rộng bằng vai, cầm tạ đơn mỗi tay, lòng bàn tay hướng về phía trước.', 'Đặt kẹp tay lên cánh tay trên, đảm bảo ôm chắc.', 'Giữ cánh tay trên đứng yên, thở ra và cuốn một tạ lên về phía vai trong khi co cơ tay trước.', 'Tiếp tục nâng tạ đến khi cơ tay trước co hết mức và tạ ngang vai.', 'Giữ tư thế co một nhịp, siết cơ tay trước.', 'Hít vào và từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại động tác với tay còn lại.', 'Tiếp tục luân phiên hai tay cho đủ số lần mong muốn.'], '{}', false, false, true),
  ('dumbbell-alternate-hammer-preacher-curl', 'dumbbell alternate hammer preacher curl', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Ngồi lên ghế preacher, cầm tạ đơn mỗi tay, lòng bàn tay hướng về thân và tay duỗi thẳng.', 'Giữ cánh tay trên đứng yên, thở ra và cuốn tạ trong khi co cơ tay trước.', 'Tiếp tục nâng tạ đến khi cơ tay trước co hết mức và tạ ngang vai.', 'Giữ tư thế co một nhịp, siết cơ tay trước.', 'Hít vào và từ từ bắt đầu hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần khuyến nghị.'], '{}', false, false, true),
