  ('dumbbell-alternate-side-press', 'dumbbell alternate side press', '{SHOULDERS,TRICEPS,CORE}', '{DUMBBELL}', ARRAY['Đứng hai chân rộng bằng vai, cầm tạ đơn mỗi tay ở ngang vai.', 'Đẩy một tạ lên trên đầu, đồng thời giữ tạ còn lại ở ngang vai.', 'Hạ tạ vừa đẩy về ngang vai, đồng thời đẩy tạ còn lại lên trên đầu.', 'Tiếp tục luân phiên hai bên cho đủ số lần mong muốn.'], '{}', false, false, true),
