  ('dumbbell-alternating-seated-bicep-curl-on-exercise-ball', 'dumbbell alternating seated bicep curl on exercise ball', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Ngồi lên bóng tập, hai chân đặt phẳng trên sàn và lưng thẳng.', 'Cầm tạ đơn mỗi tay, lòng bàn tay hướng về phía trước và tay duỗi thẳng.', 'Giữ cánh tay trên đứng yên, thở ra và cuốn một tạ trong khi xoay cẳng tay cho đến khi lòng bàn tay hướng về vai.', 'Hít vào và từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại động tác cuốn với tay còn lại.', 'Tiếp tục luân phiên cuốn cho đủ số lần mong muốn.'], '{}', false, false, true),
  ('dumbbell-arnold-press', 'dumbbell arnold press', '{SHOULDERS,TRICEPS,CHEST}', '{DUMBBELL}', ARRAY['Ngồi trên ghế có tựa lưng, cầm tạ đơn mỗi tay ngang vai, lòng bàn tay hướng vào thân và khuỷu gập.', 'Đẩy tạ lên trên cho đến khi tay duỗi thẳng và lòng bàn tay hướng về phía trước.', 'Xoay cổ tay khi nâng, để lòng bàn tay hướng về phía trước ở trên cùng của động tác.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
