  ('dumbbell-around-pullover', 'dumbbell around pullover', '{CHEST,TRICEPS,LATS}', '{DUMBBELL}', ARRAY['Nằm ngửa trên ghế, đầu ở một đầu ghế và hai chân đặt chắc trên sàn.', 'Cầm một tạ đơn bằng hai tay và duỗi thẳng tay lên trên ngực.', 'Giữ tay thẳng, từ từ hạ tạ ra sau đầu theo đường cung.', 'Dừng một nhịp ở đáy, rồi nâng tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('dumbbell-bench-press', 'dumbbell bench press', '{CHEST,TRICEPS,SHOULDERS}', '{DUMBBELL,BENCH}', ARRAY['Nằm ngửa trên ghế, hai chân đặt phẳng trên sàn và lưng ép sát ghế.', 'Cầm tạ đơn mỗi tay, lòng bàn tay hướng về phía trước và tay duỗi thẳng phía trên ngực.', 'Hạ tạ từ từ về hai bên ngực, giữ khuỷu gập 90 độ.', 'Dừng một nhịp, rồi đẩy tạ trở lại vị trí ban đầu, duỗi thẳng hết tay.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
