  ('dumbbell-one-arm-hammer-press-on-exercise-ball', 'dumbbell one arm hammer press on exercise ball', '{TRICEPS,SHOULDERS,CHEST}', '{DUMBBELL}', ARRAY['Ngồi lên bóng tập, hai chân đặt phẳng trên sàn và lưng thẳng.', 'Cầm một tạ đơn ở một tay, lòng bàn tay hướng vào trong và khuỷu gập 90 độ.', 'Đặt tay còn lại lên hông để giữ thăng bằng.', 'Đẩy tạ lên, duỗi thẳng hết tay.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi tay.'], '{}', false, false, true),
  ('dumbbell-one-arm-incline-chest-press', 'dumbbell one arm incline chest press', '{CHEST,SHOULDERS,TRICEPS}', '{DUMBBELL,BENCH}', ARRAY['Chỉnh ghế dốc lên về góc 45 độ.', 'Ngồi lên ghế, lưng tựa vào đệm, hai chân đặt phẳng trên sàn.', 'Cầm tạ đơn một tay, cầm sấp, đặt tạ lên vai.', 'Đẩy tạ lên và ra xa người, duỗi thẳng tay hết cỡ.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi sang tay kia.'], '{}', false, false, true),
  ('dumbbell-one-arm-kickback', 'dumbbell one arm kickback', '{TRICEPS,SHOULDERS}', '{DUMBBELL}', ARRAY['Đứng hai chân rộng bằng vai, tay phải cầm tạ đơn.', 'Hơi khuỵu gối, gập hông về phía trước, giữ lưng thẳng.', 'Đưa khuỷu tay phải sát sườn, giữ khuỷu gập 90 độ.', 'Duỗi thẳng tay phải ra sau, siết cơ tay sau ở cuối động tác.', 'Từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi bên.'], '{}', false, false, true),
  ('dumbbell-one-arm-lateral-raise', 'dumbbell one arm lateral raise', '{SHOULDERS,UPPER_BACK,TRICEPS}', '{DUMBBELL}', ARRAY['Đứng hai chân rộng bằng vai, cầm tạ đơn một tay, lòng bàn tay hướng vào người.', 'Giữ lưng thẳng và siết bụng suốt động tác.', 'Nâng tạ sang bên, giữ tay thẳng, lòng bàn tay hướng xuống.', 'Tiếp tục nâng đến khi tay song song với sàn.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi sang tay kia.'], '{}', false, false, true),
  ('dumbbell-one-arm-lateral-raise-with-support', 'dumbbell one arm lateral raise with support', '{SHOULDERS,UPPER_BACK}', '{DUMBBELL}', ARRAY['Đứng hai chân rộng bằng vai, cầm tạ đơn một tay, lòng bàn tay hướng vào người.', 'Tay còn lại đặt lên một chỗ vững, như ghế tập hoặc tường, để chống đỡ.', 'Giữ lưng thẳng và siết bụng.', 'Nâng tạ sang bên, giữ tay thẳng, lòng bàn tay hướng xuống.', 'Tiếp tục nâng đến khi tay song song với sàn.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi bên.'], '{}', false, false, true),
  ('dumbbell-one-arm-press-on-exercise-ball', 'dumbbell one arm press on exercise ball', '{CHEST,SHOULDERS,TRICEPS,CORE}', '{DUMBBELL}', ARRAY['Ngồi lên bóng tập, hai chân đặt phẳng trên sàn, gối gập 90 độ.', 'Cầm tạ đơn một tay, đặt tạ ngang vai, khuỷu gập, lòng bàn tay hướng về trước.', 'Từ từ đẩy tạ lên cho đến khi tay duỗi thẳng hoàn toàn, giữ bụng siết và giữ thăng bằng trên bóng.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi sang tay kia.'], '{}', false, false, true),
  ('dumbbell-one-arm-prone-curl', 'dumbbell one arm prone curl', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Nằm sấp trên ghế phẳng, tay cầm tạ đơn, lòng bàn tay hướng xuống.', 'Duỗi thẳng hết cỡ tay, để tay thõng xuống sàn.', 'Giữ cánh tay trên đứng yên, cuốn tạ lên về phía vai bằng cách co cơ tay trước.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi tay.'], '{}', false, false, true),
  ('dumbbell-one-arm-prone-hammer-curl', 'dumbbell one arm prone hammer curl', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Nằm sấp trên ghế phẳng, tay cầm tạ đơn, lòng bàn tay hướng vào người, duỗi thẳng tay hết cỡ.', 'Giữ cánh tay trên đứng yên, cuốn tạ về phía vai bằng cách co cơ tay trước.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi tay.'], '{}', false, false, true),
  ('dumbbell-one-arm-pullover-on-exercise-ball', 'dumbbell one arm pullover on exercise ball', '{CHEST,TRICEPS,LATS,UPPER_BACK}', '{DUMBBELL}', ARRAY['Ngồi lên bóng tập, hai chân đặt phẳng trên sàn, gối gập 90 độ.', 'Cầm tạ đơn một tay, duỗi thẳng tay lên trên ngực.', 'Từ từ hạ tạ ra sau đầu, giữ tay thẳng.', 'Dừng một nhịp, rồi nâng tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi tay.'], '{}', false, false, true),
  ('dumbbell-one-arm-reverse-wrist-curl', 'dumbbell one arm reverse wrist curl', '{FOREARMS}', '{DUMBBELL}', ARRAY['Ngồi trên ghế hoặc ghế đẩu, hai chân đặt phẳng trên sàn.', 'Cầm tạ đơn một tay, cầm sấp, lòng bàn tay hướng xuống.', 'Đặt cẳng tay lên đùi, để cổ tay thõng ra khỏi mép.', 'Từ từ hạ tạ xuống bằng cách gập cổ tay.', 'Dừng một nhịp ở dưới cùng, rồi từ từ cuốn cổ tay lên về phía cơ thể.', 'Lặp lại đủ số lần mong muốn, rồi đổi sang tay kia.'], '{}', false, false, true),
  ('dumbbell-one-arm-reverse-fly-with-support', 'dumbbell one arm reverse fly (with support)', '{SHOULDERS,UPPER_BACK}', '{DUMBBELL}', ARRAY['Ngồi trên ghế, hai chân đặt phẳng trên sàn, lưng thẳng.', 'Cầm tạ đơn một tay, lòng bàn tay hướng vào trong.', 'Cúi người về trước, tay còn lại đặt lên ghế để chống đỡ.', 'Giữ tay hơi gập, nâng tay sang bên đến khi song song với sàn.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tay về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi tay.'], '{}', false, false, true),
  ('dumbbell-one-arm-reverse-grip-press', 'dumbbell one arm reverse grip press', '{CHEST,TRICEPS,SHOULDERS}', '{DUMBBELL}', ARRAY['Ngồi trên ghế phẳng, cầm tạ đơn một tay, lòng bàn tay hướng về phía người.', 'Đặt hai chân phẳng trên sàn, giữ lưng thẳng.', 'Nâng tạ lên ngang vai, giữ khuỷu sát người.', 'Đẩy tạ lên cho đến khi tay duỗi thẳng hết cỡ.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi sang tay kia.'], '{}', false, false, true),
  ('dumbbell-one-arm-reverse-preacher-curl', 'dumbbell one arm reverse preacher curl', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Ngồi trên ghế Preacher, ngực tựa vào đệm, tay duỗi qua mép ghế, cầm tạ đơn bằng cách cầm ngửa.', 'Hạ tạ từ từ cho đến khi tay duỗi thẳng hết cỡ.', 'Cuốn tạ lên về phía vai, giữ cánh tay trên đứng yên.', 'Siết cơ tay trước ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi tay.'], '{}', false, false, true),
