  ('dumbbell-one-arm-seated-bicep-curl-on-exercise-ball', 'dumbbell one arm seated bicep curl on exercise ball', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Ngồi lên bóng tập, hai chân đặt phẳng trên sàn, lưng thẳng.', 'Cầm tạ đơn một tay, lòng bàn tay hướng lên, duỗi thẳng tay.', 'Giữ cánh tay trên đứng yên, cuốn tạ về phía vai bằng cách co cơ tay trước.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi tay.'], '{}', false, false, true),
  ('dumbbell-one-arm-seated-hammer-curl', 'dumbbell one arm seated hammer curl', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Ngồi trên ghế, lưng thẳng, hai chân đặt phẳng trên sàn.', 'Cầm tạ đơn một tay, cầm trung tính (lòng bàn tay quay vào nhau).', 'Đặt khuỷu tay lên mặt trong đùi, ngay trên đầu gối.', 'Giữ cánh tay trên đứng yên, thở ra và cuốn tạ lên về phía vai.', 'Dừng một nhịp ở trên cùng, siết cơ tay trước.', 'Hít vào và từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi tay.'], '{}', false, false, true),
  ('dumbbell-one-arm-seated-neutral-wrist-curl', 'dumbbell one arm seated neutral wrist curl', '{FOREARMS,BICEPS}', '{DUMBBELL}', ARRAY['Ngồi trên ghế, hai chân đặt phẳng trên sàn, cầm tạ đơn một tay, lòng bàn tay hướng lên.', 'Đặt cẳng tay lên đùi, để cổ tay thõng ra khỏi mép.', 'Giữ cẳng tay đứng yên, gập cổ tay lên cao hết mức có thể.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ cổ tay về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi sang tay kia.'], '{}', false, false, true),
  ('dumbbell-one-arm-shoulder-press', 'dumbbell one arm shoulder press', '{SHOULDERS,TRICEPS,UPPER_BACK}', '{DUMBBELL}', ARRAY['Đứng hai chân rộng bằng vai, cầm tạ đơn một tay ngang vai, lòng bàn tay hướng về trước.', 'Đẩy tạ lên cho đến khi tay duỗi thẳng qua đầu.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi sang tay kia.'], '{}', false, false, true),
  ('dumbbell-one-arm-shoulder-press-v-2', 'dumbbell one arm shoulder press v. 2', '{SHOULDERS,TRICEPS,UPPER_BACK}', '{DUMBBELL}', ARRAY['Đứng hai chân rộng bằng vai, cầm tạ đơn một tay ngang vai, lòng bàn tay hướng về trước.', 'Siết bụng và đẩy tạ thẳng lên trên đầu, duỗi thẳng tay hết cỡ.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tạ về ngang vai.', 'Lặp lại đủ số lần mong muốn, rồi đổi sang tay kia.'], '{}', false, false, true),
  ('dumbbell-one-arm-snatch', 'dumbbell one arm snatch', '{GLUTES,HAMSTRINGS,QUADS,CORE}', '{DUMBBELL}', ARRAY['Đứng hai chân rộng bằng vai, cầm tạ đơn một tay, cầm sấp.', 'Hơi khuỵu gối, gập hông về phía trước, giữ lưng thẳng và ngực ưỡn.', 'Hạ tạ xuống gần sàn, giữ tạ sát người.', 'Bật mạnh hông, gối và cổ chân, đẩy tạ lên theo đường thẳng.', 'Khi tạ lên ngang vai, nhanh chóng xoay cổ tay và đẩy tạ lên trên đầu, duỗi thẳng tay.', 'Đón tạ trên đầu khi hơi khuỵu gối và hông.', 'Hạ tạ về vị trí ban đầu một cách có kiểm soát.', 'Lặp lại đủ số lần mong muốn, rồi đổi sang tay kia.'], '{}', false, false, true)
