INSERT INTO exercises (slug, name_en, muscle_groups, equipment, steps_vi, mistakes_vi, analyzable, is_active, is_draft) VALUES
  ('dumbbell-one-arm-standing-curl', 'dumbbell one arm standing curl', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Đứng thẳng, cầm tạ đơn một tay, lòng bàn tay hướng về trước, duỗi thẳng tay.', 'Giữ cánh tay trên đứng yên, thở ra và cuốn tạ lên trong khi co cơ tay trước.', 'Tiếp tục nâng tạ cho đến khi cơ tay trước co hết cỡ và tạ ngang vai.', 'Giữ tư thế co một nhịp, siết cơ tay trước.', 'Hít vào và từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi tay.'], '{}', false, false, true),
  ('dumbbell-one-arm-standing-hammer-curl', 'dumbbell one arm standing hammer curl', '{BICEPS,FOREARMS}', '{DUMBBELL}', ARRAY['Đứng thẳng, cầm mỗi tay một tạ đơn, lòng bàn tay hướng vào thân người.', 'Giữ khuỷu tay sát thân người và cánh tay trên đứng yên.', 'Thở ra và cuốn tạ lên trong khi co cơ tay trước.', 'Tiếp tục nâng tạ cho đến khi cơ tay trước co hết cỡ và tạ ngang vai.', 'Giữ tư thế co một nhịp, siết cơ tay trước.', 'Hít vào và bắt đầu hạ tạ về vị trí ban đầu từ từ.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('dumbbell-one-arm-triceps-extension-on-bench', 'dumbbell one arm triceps extension (on bench)', '{TRICEPS,SHOULDERS}', '{DUMBBELL,BENCH}', ARRAY['Ngồi trên ghế, lưng thẳng, hai chân đặt phẳng trên sàn.', 'Cầm tạ đơn một tay, tay còn lại chống lên ghế.', 'Nâng tạ lên trên đầu, giữ khuỷu tay sát đầu, mũi khuỷu hướng về trước.', 'Hạ tạ ra sau đầu bằng cách gập khuỷu, giữ cánh tay trên đứng yên.', 'Duỗi tay trở lại vị trí ban đầu, duỗi thẳng khuỷu hết cỡ.', 'Lặp lại đủ số lần mong muốn, rồi đổi tay.'], '{}', false, false, true),
  ('dumbbell-one-arm-upright-row', 'dumbbell one arm upright row', '{SHOULDERS,UPPER_BACK,BICEPS}', '{DUMBBELL}', ARRAY['Đứng hai chân rộng bằng vai, cầm tạ đơn một tay, cầm sấp.', 'Để tạ thõng thẳng tay trước đùi, lòng bàn tay hướng về người.', 'Giữ lưng thẳng, siết bụng, thở ra và kéo tạ thẳng lên về phía cằm, dẫn dắt bằng khuỷu tay.', 'Dừng một nhịp ở trên cùng, rồi hít vào và từ từ hạ tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi sang tay kia.'], '{}', false, false, true),
