  ('elbow-to-knee', 'elbow-to-knee', '{CORE}', '{}', ARRAY['Bắt đầu bằng cách nằm ngửa trên sàn, gối gập và hai bàn chân đặt phẳng trên sàn.', 'Đặt hai tay sau đầu, khuỷu hướng ra ngoài.', 'Siết cơ bụng và nâng thân trên khỏi sàn, đưa khuỷu tay phải về phía đầu gối trái.', 'Đồng thời đưa đầu gối trái về phía khuỷu tay phải, tạo động tác xoắn.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thân trên và duỗi chân về vị trí ban đầu.', 'Lặp lại động tác, lần này đưa khuỷu tay trái về phía đầu gối phải và đầu gối phải về phía khuỷu tay trái.', 'Tiếp tục luân phiên hai bên cho đủ số lần mong muốn.'], '{}', false, false, true),
  ('elevator', 'elevator', '{UPPER_BACK,SHOULDERS}', '{}', ARRAY['Đứng hai chân rộng bằng vai, gối hơi gập.', 'Đặt hai tay lên hông hoặc khoanh trước ngực.', 'Giữ lưng thẳng, từ từ cúi thân trên về trước ở thắt lưng, hạ thân trên về phía sàn.', 'Dừng một nhịp ở dưới cùng, rồi từ từ nâng thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-alternating-arm-ups', 'exercise ball alternating arm ups', '{LATS,SHOULDERS,CORE}', '{BALL}', ARRAY['Ngồi trên bóng tập, hai chân đặt phẳng trên sàn, lưng thẳng.', 'Mỗi tay cầm một tạ đơn, lòng bàn tay hướng vào trong, hai tay thõng bên hông.', 'Siết bụng và từ từ nâng một tay lên về phía vai, giữ khuỷu hơi gập.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tay về vị trí ban đầu.', 'Lặp lại động tác với tay còn lại.', 'Tiếp tục luân phiên hai tay cho đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-back-extension-with-arms-extended', 'exercise ball back extension with arms extended', '{LOWER_BACK,GLUTES,HAMSTRINGS}', '{BALL}', ARRAY['Đặt bóng tập trên sàn, nằm sấp trên bóng, hông tựa lên bóng và hai bàn chân tựa vào tường để giữ thăng bằng.', 'Duỗi thẳng hai tay ra trước, lòng bàn tay hướng xuống.', 'Siết bụng và từ từ nâng thân trên khỏi bóng, giữ lưng thẳng và cổ thẳng theo cột sống.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-back-extension-with-hands-behind-head', 'exercise ball back extension with hands behind head', '{LOWER_BACK,GLUTES,HAMSTRINGS}', '{BALL}', ARRAY['Đặt bóng tập trên sàn, nằm sấp trên bóng với hông tựa lên bóng.', 'Đặt hai bàn chân tựa vào tường hoặc bề mặt chắc khác để chống đỡ.', 'Khoanh hai tay sau đầu, lòng bàn tay chạm sau đầu.', 'Siết bụng và từ từ nâng thân trên khỏi bóng, duỗi lưng cho đến khi cơ thể tạo thành một đường thẳng từ đầu đến hông.', 'Dừng một nhịp ở trên cùng động tác, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-back-extension-with-knees-off-ground', 'exercise ball back extension with knees off ground', '{LOWER_BACK,GLUTES,HAMSTRINGS}', '{BALL}', ARRAY['Đặt bóng tập trên sàn, nằm sấp trên bóng, hông tựa lên bóng và hai bàn chân tựa vào tường để giữ thăng bằng.', 'Đặt hai tay sau đầu hoặc khoanh trước ngực.', 'Siết bụng và từ từ nâng thân trên khỏi bóng, duỗi lưng cho đến khi cơ thể tạo thành một đường thẳng từ đầu đến gót chân.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-back-extension-with-rotation', 'exercise ball back extension with rotation', '{LOWER_BACK,GLUTES,HAMSTRINGS}', '{BALL}', ARRAY['Bắt đầu bằng cách nằm sấp trên bóng tập, hông tựa lên bóng và hai chân đặt chắc trên sàn.', 'Đặt hai tay sau đầu hoặc khoanh trước ngực.', 'Siết bụng và từ từ nâng thân trên khỏi bóng, duỗi lưng cho đến khi cơ thể tạo thành một đường thẳng từ đầu đến gót chân.', 'Dừng một nhịp ở trên cùng, rồi từ từ xoay thân trên sang một bên, giữ hông và chân ổn định.', 'Quay về giữa và xoay sang bên kia.', 'Hạ thân trên về vị trí ban đầu và lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-dip', 'exercise ball dip', '{TRICEPS,CHEST,SHOULDERS}', '{BALL}', ARRAY['Ngồi trên bóng tập, hai chân đặt phẳng trên sàn, gối gập 90 độ.', 'Đặt hai tay lên bóng cạnh hông, ngón tay hướng về trước.', 'Siết cơ tay sau và đẩy qua hai tay để nâng người khỏi bóng, duỗi thẳng tay.', 'Hạ người xuống bằng cách gập khuỷu, giữ khuỷu sát sườn.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-hip-flexor-stretch', 'exercise ball hip flexor stretch', '{GLUTES,QUADS,HAMSTRINGS}', '{BALL}', ARRAY['Đặt bóng tập trên sàn, quỳ trước bóng.', 'Đặt chân phải lên trên bóng, gối gập 90 độ.', 'Duỗi thẳng chân trái ra sau.', 'Nghiêng người về trước, đẩy hông về phía bóng, cho đến khi cảm thấy căng ở cơ gập hông phải.', 'Giữ kéo giãn 20-30 giây, rồi đổi bên và lặp lại.'], '{}', false, false, true),
  ('exercise-ball-hug', 'exercise ball hug', '{LOWER_BACK,SHOULDERS,CHEST}', '{BALL}', ARRAY['Ngồi lên bóng tập, hai chân đặt phẳng trên sàn, lưng thẳng.', 'Hai tay ôm bóng tập sát ngực.', 'Siết cơ bụng và từ từ ngả người ra sau, giữ lưng thẳng và hai chân đặt chắc trên sàn.', 'Tiếp tục ngả ra sau cho đến khi cảm thấy căng ở cơ lưng.', 'Giữ tư thế vài giây, rồi từ từ trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-lat-stretch', 'exercise ball lat stretch', '{LATS,SHOULDERS,TRICEPS}', '{BALL}', ARRAY['Ngồi trên bóng tập, hai chân đặt phẳng trên sàn, lưng thẳng.', 'Cầm một tạ đơn bằng một tay và duỗi thẳng tay lên trên đầu.', 'Từ từ nghiêng người sang bên đối diện, cảm nhận căng ở cơ xô.', 'Giữ kéo giãn 20-30 giây, rồi trở về vị trí ban đầu.', 'Lặp lại ở bên kia.'], '{}', false, false, true),
  ('exercise-ball-lower-back-stretch-pyramid', 'exercise ball lower back stretch (pyramid)', '{LATS,GLUTES,HAMSTRINGS}', '{BALL}', ARRAY['Ngồi lên bóng tập, hai chân đặt phẳng trên sàn, gối gập 90 độ.', 'Từ từ bước chân về trước, lăn bóng xuống lưng cho đến khi lưng dưới tựa lên bóng.', 'Đặt hai tay sau đầu hoặc khoanh trước ngực.', 'Siết bụng và từ từ hạ thân trên về phía sàn, để lưng dưới giãn trên bóng.', 'Giữ kéo giãn vài giây, rồi từ từ trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-lying-side-lat-stretch', 'exercise ball lying side lat stretch', '{LATS,SHOULDERS,TRICEPS}', '{BALL}', ARRAY['Nằm nghiêng, hai chân duỗi thẳng và đầu được bóng tập đỡ.', 'Đặt tay trên lên bóng để giữ thăng bằng.', 'Đưa tay trên qua đầu và cho thân người xoay nhẹ.', 'Cảm nhận căng ở cơ xô bên sườn cơ thể.', 'Giữ kéo giãn 20-30 giây, rồi đổi bên và lặp lại.'], '{}', false, false, true),
