  ('exercise-ball-one-leg-prone-lower-body-rotation', 'exercise ball one leg prone lower body rotation', '{GLUTES,HAMSTRINGS,QUADS,CORE}', '{BALL}', ARRAY['Nằm sấp trên bóng tập, hông tựa lên bóng, hai chân duỗi thẳng ra sau.', 'Đặt hai tay xuống sàn trước người để chống đỡ.', 'Siết cơ mông và cơ bụng để giữ cơ thể ổn định.', 'Từ từ nâng một chân khỏi sàn, giữ chân thẳng và song song với sàn.', 'Xoay chân ra ngoài, rời khỏi thân người, trong khi giữ hông và thân trên ổn định.', 'Dừng một nhịp ở cuối động tác xoay, rồi từ từ đưa chân về vị trí ban đầu.', 'Lặp lại động tác xoay với chân còn lại.', 'Tiếp tục luân phiên hai chân cho đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-one-legged-diagonal-kick-hamstring-curl', 'exercise ball one legged diagonal kick hamstring curl', '{GLUTES,HAMSTRINGS,CALVES}', '{BALL}', ARRAY['Bắt đầu bằng cách nằm ngửa, hai chân duỗi thẳng và gót chân đặt lên trên bóng tập.', 'Đặt hai tay sát hai bên người để giữ thăng bằng.', 'Siết cơ mông và cơ bụng để nâng hông khỏi sàn, tạo một đường thẳng từ vai đến gót chân.', 'Gập gối phải và đưa về phía ngực, giữ chân trái duỗi thẳng và mũi bàn chân gập.', 'Đá chân phải chéo qua thân người, duỗi thẳng hết cỡ và siết cơ đùi sau.', 'Từ từ đưa chân phải về vị trí ban đầu, giữ kiểm soát và thăng bằng.', 'Lặp lại động tác với chân trái, luân phiên hai bên cho đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-pike-push-up', 'exercise ball pike push up', '{CHEST,SHOULDERS,TRICEPS,CORE}', '{BALL}', ARRAY['Bắt đầu ở tư thế chống đẩy, hai tay đặt trên sàn và ống chân đặt lên bóng tập.', 'Siết bụng và nâng hông lên về phía trần nhà, lăn bóng về phía hai tay.', 'Giữ hai chân thẳng và cơ thể ở tư thế pike, tạo thành hình chữ V ngược.', 'Gập khuỷu và hạ thân trên về phía sàn, giữ đầu thẳng hàng với hai tay.', 'Đẩy qua hai tay và duỗi thẳng tay để về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-prone-leg-raise', 'exercise ball prone leg raise', '{LOWER_BACK,CORE,GLUTES}', '{BALL}', ARRAY['Nằm sấp trên thảm, duỗi thẳng hai chân và đặt mũi chân lên trên bóng tập.', 'Đặt hai tay xuống sàn, rộng bằng vai, và siết cơ bụng.', 'Giữ chân thẳng, từ từ nâng chân khỏi sàn, dùng cơ lưng dưới và mông để nâng chân cao hết mức có thể.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('exercise-ball-seated-hamstring-stretch', 'exercise ball seated hamstring stretch', '{HAMSTRINGS,GLUTES,LOWER_BACK}', '{BALL}', ARRAY['Ngồi lên bóng tập, hai chân đặt phẳng trên sàn, gối gập 90 độ.', 'Từ từ lăn bóng về trước, bước chân ra cho đến khi lưng trên tựa lên bóng và hai chân duỗi thẳng trước người.', 'Đặt hai tay lên hông để chống đỡ.', 'Siết bụng và từ từ hạ thân trên về phía sàn, giữ lưng thẳng và ngực ưỡn.', 'Dừng khi cảm thấy căng ở đùi sau, và giữ tư thế 20-30 giây.', 'Từ từ trở về vị trí ban đầu bằng cách đẩy qua gót chân và dùng cơ đùi sau để kéo người lên.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
