  ('floor-fly-with-barbell', 'floor fly (with barbell)', '{CHEST,SHOULDERS,TRICEPS}', '{BARBELL_RACK}', ARRAY['Nằm ngửa trên sàn, gập gối, hai bàn chân đặt chắc trên sàn.', 'Cầm tạ đòn kiểu cầm sấp, duỗi thẳng hai tay lên trên ngực.', 'Từ từ hạ tạ sang hai bên, giữ khuỷu tay hơi gập.', 'Hạ tạ tới khi cánh tay song song với sàn, cảm nhận cơ ngực căng ra.', 'Dừng một lúc, rồi siết cơ ngực đưa tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('flutter-kicks', 'flutter kicks', '{GLUTES,CORE}', '{}', ARRAY['Nằm ngửa, duỗi thẳng chân, hai tay để sát hai bên thân.', 'Siết cơ bụng, nâng hai chân khỏi sàn khoảng 6 inch.', 'Giữ chân thẳng, luân phiên nâng một chân cao hơn chân kia.', 'Lặp lại động tác đạp này đủ số lần mong muốn.'], '{}', false, false, true),
  ('forward-jump', 'forward jump', '{QUADS,CALVES,HAMSTRINGS,GLUTES}', '{}', ARRAY['Đứng hai chân rộng bằng vai.', 'Gập gối, hạ người xuống tư thế squat.', 'Vung tay ra sau để lấy đà.', 'Bật nhảy về phía trước, duỗi hông, gối và cổ chân hết lực.', 'Tiếp đất nhẹ bằng phần trước bàn chân rồi nhảy tiếp ngay.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('forward-lunge-male', 'forward lunge (male)', '{GLUTES,QUADS,HAMSTRINGS,CALVES}', '{}', ARRAY['Đứng hai chân rộng bằng hông, hai tay chống hông.', 'Bước một bước dài về phía trước bằng chân phải, hạ người vào tư thế lunge.', 'Gập gối phải khoảng 90 độ, giữ gối thẳng hàng với mắt cá.', 'Đẩy chân phải và trở về vị trí ban đầu.', 'Lặp lại với chân trái, luân phiên hai bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('frankenstein-squat', 'frankenstein squat', '{GLUTES,QUADS,HAMSTRINGS,CALVES}', '{BARBELL_RACK}', ARRAY['Đứng hai chân rộng bằng vai, cầm tạ đòn phía trước người, hai tay thẳng.', 'Giữ lưng thẳng, hạ người bằng cách gập gối và hông, như ngồi xuống ghế.', 'Tiếp tục hạ tới khi đùi song song với sàn, hoặc thấp nhất có thể thoải mái.', 'Dừng một lúc, rồi đẩy qua gót chân để về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('frog-crunch', 'frog crunch', '{CORE}', '{}', ARRAY['Nằm ngửa, gập gối, hai bàn chân đặt chắc trên sàn.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết cơ bụng, nâng thân trên khỏi sàn, cuộn người về phía trước tới khi thân tạo góc 45 độ.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('frog-planche', 'frog planche', '{CORE,SHOULDERS,CHEST,TRICEPS}', '{}', ARRAY['Bắt đầu ở tư thế chống đẩy, hai tay rộng bằng vai, hai chân khép lại.', 'Gập khuỷu tay, hạ người về phía sàn, giữ lưng thẳng.', 'Khi hạ người, nhấc hai chân khỏi sàn và đưa đầu gối về phía ngực.', 'Giữ tư thế này vài giây, rồi duỗi chân ra và đẩy người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('front-lever', 'front lever', '{CORE,LATS,SHOULDERS,FOREARMS}', '{}', ARRAY['Bắt đầu bằng cách treo trên xà, cầm sấp, hai tay rộng bằng vai.', 'Siết cơ bụng, kéo xương bả vai xuống và ra sau.', 'Gập gối, co chân về phía ngực.', 'Đồng thời, nâng chân lên và duỗi thẳng ra phía trước, giữ thân song song với sàn.', 'Giữ tư thế này càng lâu càng tốt, hướng tới tư thế front lever đầy đủ.', 'Để thả ra, từ từ hạ chân xuống và trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('front-lever-reps', 'front lever reps', '{UPPER_BACK,CORE,SHOULDERS}', '{}', ARRAY['Treo trên xà, cầm sấp, lòng bàn tay quay ra xa người.', 'Siết cơ bụng, kéo xương bả vai xuống và ra sau.', 'Giữ thân thẳng, nâng chân tới khi song song với sàn.', 'Giữ tư thế này càng lâu càng tốt, hướng tới 10-20 giây.', 'Từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('front-plank-with-twist', 'front plank with twist', '{CORE,SHOULDERS}', '{}', ARRAY['Bắt đầu ở tư thế plank cao, hai tay đặt ngay dưới vai, thân thẳng từ đầu tới gót chân.', 'Siết cơ bụng và cơ mông để giữ thân ổn định.', 'Xoay thân sang phải, nâng tay phải và duỗi về phía trần nhà.', 'Giữ hông và chân ổn định khi xoay.', 'Giữ một lúc, rồi trở về vị trí ban đầu.', 'Lặp lại động tác xoay sang bên trái.', 'Luân phiên hai bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('full-maltese', 'full maltese', '{CORE,SHOULDERS,CHEST}', '{}', ARRAY['Bắt đầu đứng hai chân rộng bằng vai, hai tay duỗi thẳng sang hai bên.', 'Từ từ nghiêng người về phía trước, giữ tay thẳng, tới khi thân trên song song với sàn.', 'Siết cơ bụng và giữ tư thế này vài giây.', 'Trở về vị trí ban đầu bằng cách đẩy qua chân và đứng thẳng lên.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('full-planche', 'full planche', '{CORE,SHOULDERS,CHEST,TRICEPS}', '{}', ARRAY['Bắt đầu ở tư thế chống đẩy, hai tay rộng bằng vai, ngón tay hướng về phía trước.', 'Siết cơ bụng và từ từ dồn trọng lượng về phía trước, nhấc chân khỏi sàn.', 'Tiếp tục dồn trọng lượng về phía trước tới khi thân song song với sàn, cân bằng trên hai tay.', 'Giữ tư thế này càng lâu càng tốt, giữ thân thẳng.', 'Từ từ hạ chân xuống sàn và trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('full-planche-push-up', 'full planche push-up', '{CHEST,SHOULDERS,TRICEPS,CORE}', '{}', ARRAY['Bắt đầu ở tư thế chống đẩy, hai tay đặt rộng hơn vai một chút.', 'Siết cơ bụng, hạ người xuống sàn, giữ khuỷu tay sát thân.', 'Khi hạ người, nghiêng thân về trước và nhấc chân khỏi sàn, cân bằng trên hai tay.', 'Tiếp tục hạ người tới khi ngực vừa trên sàn.', 'Đẩy qua hai tay và duỗi thẳng tay để nâng người về vị trí ban đầu.', 'Giữ thân thẳng từ đầu tới gót chân suốt động tác.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO exercises (slug, name_en, muscle_groups, equipment, steps_vi, mistakes_vi, analyzable, is_active, is_draft) VALUES
  ('gironda-sternum-chin', 'gironda sternum chin', '{LATS,BICEPS,UPPER_BACK,SHOULDERS}', '{}', ARRAY['Đứng đối diện xà cao, hai chân rộng bằng vai.', 'Với tay nắm xà kiểu cầm sấp, rộng hơn vai một chút.', 'Treo trên xà, duỗi thẳng hết hai tay, thân thẳng.', 'Siết cơ xô và cơ tay trước để kéo ngực lên về phía xà, dẫn đầu bằng xương ức.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('glute-bridge-march', 'glute bridge march', '{GLUTES,HAMSTRINGS,QUADS}', '{}', ARRAY['Nằm ngửa, gập gối, hai bàn chân đặt chắc trên sàn.', 'Siết cơ mông, nhấc hông khỏi sàn tạo thành đường thẳng từ đầu gối tới vai.', 'Giữ hông nhấc, nhấc một chân khỏi sàn và đưa đầu gối về phía ngực.', 'Hạ chân về sàn rồi lặp lại động tác với chân kia.', 'Luân phiên hai chân theo kiểu bước đi, giữ tư thế cầu mông.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('glute-bridge-two-legs-on-bench-male', 'glute bridge two legs on bench (male)', '{GLUTES,HAMSTRINGS,CORE}', '{BENCH}', ARRAY['Ngồi ở mép ghế, lưng tựa vào ghế, hai bàn chân đặt chắc trên sàn.', 'Đặt hai tay lên ghế cạnh hông để giữ thăng bằng.', 'Siết cơ mông và cơ đùi sau, rồi nhấc hông khỏi ghế tới khi người tạo thành đường thẳng từ đầu gối tới vai.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ hông về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('glute-ham-raise', 'glute-ham raise', '{HAMSTRINGS,GLUTES,LOWER_BACK}', '{}', ARRAY['Chỉnh máy glute-ham raise cho vừa với cơ thể.', 'Nằm sấp trên máy, cố định mắt cá chân.', 'Đặt hai tay lên ngực hoặc khoanh tay trước ngực.', 'Siết cơ đùi sau và cơ mông để nâng thân trên hướng lên trần nhà.', 'Tiếp tục nâng tới khi người thẳng từ đầu tới gót chân.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('gorilla-chin', 'gorilla chin', '{CORE,FOREARMS,BICEPS}', '{}', ARRAY['Đứng hai chân rộng bằng vai, gối hơi gập.', 'Nắm xà kiểu cầm sấp, rộng hơn vai một chút.', 'Treo trên xà, duỗi thẳng hết hai tay, lòng bàn tay quay ra xa người.', 'Siết cơ bụng và kéo người lên về phía xà, đưa cằm lên trên xà.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('groin-crunch', 'groin crunch', '{CORE,ADDUCTORS}', '{}', ARRAY['Nằm ngửa, gập gối, hai bàn chân đặt chắc trên sàn.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết cơ bụng, nâng hai chân khỏi sàn và đưa đầu gối về phía ngực.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('hack-calf-raise', 'hack calf raise', '{CALVES,HAMSTRINGS,GLUTES}', '{MACHINE}', ARRAY['Chỉnh máy đẩy (sled) tới mức tạ vừa sức.', 'Đứng trên máy đẩy, đầu ngón chân đặt trên bệ, gót chân thõng ra ngoài.', 'Giữ tay cầm để giữ thăng bằng.', 'Nhấc gót chân cao nhất có thể bằng cách đẩy qua phần trước bàn chân.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ gót chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('hack-one-leg-calf-raise', 'hack one leg calf raise', '{CALVES,HAMSTRINGS,GLUTES}', '{MACHINE}', ARRAY['Chỉnh máy đẩy (sled) tới mức tạ phù hợp.', 'Đứng trên máy đẩy bằng một chân, chân còn lại nhấc khỏi mặt máy.', 'Giữ tay cầm để giữ thăng bằng.', 'Nhấc gót chân cao nhất có thể, nâng người lên bằng phần trước bàn chân.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ gót chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.', 'Đổi chân và lặp lại bài tập.'], '{}', false, false, true),
  ('half-knee-bends-male', 'half knee bends (male)', '{CARDIO,QUADS,HAMSTRINGS,GLUTES}', '{}', ARRAY['Đứng hai chân rộng bằng vai.', 'Gập gối và hạ người xuống như đang ngồi xuống ghế.', 'Giữ ngực thẳng, dồn trọng lượng vào gót chân.', 'Dừng một lúc ở dưới cùng, rồi đẩy qua gót chân để về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('half-sit-up-male', 'half sit-up (male)', '{CORE}', '{}', ARRAY['Nằm ngửa, gập gối, hai bàn chân đặt chắc trên sàn.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết cơ bụng, từ từ nâng thân trên khỏi sàn, cuộn người về phía trước tới khi thân tạo góc 45 độ.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('hamstring-stretch', 'hamstring stretch', '{HAMSTRINGS,GLUTES}', '{}', ARRAY['Đứng hai chân rộng bằng vai.', 'Bước chân phải lên trước và dồn trọng lượng vào chân phải.', 'Giữ lưng thẳng, từ từ gập hông về phía trước, hai tay với về phía bàn chân phải.', 'Giữ tư thế giãn trong 20-30 giây, rồi trở về vị trí ban đầu.', 'Lặp lại bên kia.'], '{}', false, false, true),
  ('hands-bike', 'hands bike', '{CHEST,TRICEPS,SHOULDERS}', '{MACHINE}', ARRAY['Chỉnh độ cao yên và vị trí tay lái tới mức thoải mái.', 'Ngồi lên xe ergometer, lưng thẳng, hai chân đặt trên bàn đạp.', 'Nắm tay cầm, đặt hai cánh tay tạo góc 90 độ.', 'Bắt đầu đạp bằng tay, đẩy và kéo tay cầm một cách có kiểm soát.', 'Tiếp tục đạp trong thời gian hoặc số lần mong muốn.'], '{}', false, false, true),
  ('hands-clasped-circular-toe-touch-male', 'hands clasped circular toe touch (male)', '{GLUTES,HAMSTRINGS,QUADS,CALVES}', '{}', ARRAY['Đứng hai chân rộng bằng vai, hai tay đan vào nhau trước ngực.', 'Gập gối nhẹ và cúi người từ hông, giữ lưng thẳng.', 'Hạ tay về phía ngón chân theo chuyển động tròn, với xa nhất có thể mà không gắng sức.', 'Dừng một lúc ở dưới cùng, rồi từ từ trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('hands-reversed-clasped-circular-toe-touch-male', 'hands reversed clasped circular toe touch (male)', '{GLUTES,HAMSTRINGS,QUADS,CALVES}', '{}', ARRAY['Đứng hai chân rộng bằng vai, hai tay duỗi sang hai bên.', 'Cúi người từ eo, giữ lưng thẳng và gối hơi gập.', 'Với tay xuống và đan hai tay ra sau chân.', 'Từ từ nâng tay lên và qua đầu theo chuyển động tròn, giữ chân thẳng.', 'Tiếp tục chuyển động tròn tới khi tay chạm ngón chân.', 'Đảo chiều chuyển động và đưa tay về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('handstand', 'handstand', '{TRICEPS,SHOULDERS,CORE}', '{}', ARRAY['Tìm chỗ trống đủ rộng để làm handstand.', 'Đặt hai tay xuống sàn rộng bằng vai, ngón tay hướng về phía trước.', 'Đá chân lên về phía tường, dùng cơ bụng và vai để giữ thăng bằng.', 'Khi đã ở tư thế handstand, siết cơ tay sau để đỡ trọng lượng cơ thể.', 'Giữ tư thế handstand càng lâu càng tốt khi còn giữ được thăng bằng.', 'Để hạ xuống, từ từ hạ chân về sàn.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('handstand-push-up', 'handstand push-up', '{TRICEPS,SHOULDERS,CHEST,CORE}', '{}', ARRAY['Tìm tường, quay lưng lại và đứng cách tường vài bước chân.', 'Đặt hai tay xuống sàn rộng bằng vai, đá chân lên sát tường để vào tư thế handstand.', 'Gập khuỷu tay, hạ đầu về phía sàn, giữ thân thẳng.', 'Đẩy qua hai tay và duỗi thẳng tay để về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('hanging-leg-hip-raise', 'hanging leg hip raise', '{CORE,LOWER_BACK}', '{}', ARRAY['Treo trên xà, hai tay duỗi thẳng, lòng bàn tay quay ra xa người.', 'Siết cơ bụng và nâng chân bằng cách gập hông và gối tới khi đùi song song với sàn.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('hanging-leg-raise', 'hanging leg raise', '{CORE}', '{}', ARRAY['Treo trên xà, hai tay duỗi thẳng, lòng bàn tay quay ra xa người.', 'Siết cơ bụng và nâng chân về phía trước, giữ chân thẳng.', 'Tiếp tục nâng tới khi chân song song với sàn hoặc cao nhất mà vẫn thoải mái.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
