  ('inverted-row-on-bench', 'inverted row on bench', '{UPPER_BACK,BICEPS,FOREARMS}', '{BENCH}', ARRAY['Chỉnh ghế ở độ cao để thân có thể treo tự do bên dưới.', 'Nằm ngửa trên sàn, đầu hướng về phía ghế.', 'Với tay lên nắm ghế kiểu cầm sấp, rộng hơn vai một chút.', 'Đặt người sao cho gót chân chạm sàn và hai tay duỗi thẳng.', 'Siết cơ bụng và ép hai xương bả vai lại gần nhau khi kéo ngực lên về phía ghế.', 'Dừng một lúc ở trên cùng của động tác, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('inverted-row-v-2', 'inverted row v. 2', '{UPPER_BACK,BICEPS,FOREARMS}', '{}', ARRAY['Đặt thanh ngang eo trên máy Smith hoặc dùng dây treo (suspension trainer).', 'Đứng quay mặt vào thanh hoặc dây treo, nắm bằng kiểu cầm sấp, hai tay rộng bằng vai.', 'Bước chân về phía trước, ngả người ra sau tới khi thân nghiêng nhẹ.', 'Giữ thân thẳng và kéo ngực lên về phía thanh hoặc tay cầm, ép hai xương bả vai lại gần nhau.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('inverted-row-with-straps', 'inverted row with straps', '{UPPER_BACK,BICEPS,FOREARMS}', '{}', ARRAY['Đặt dây treo (suspension trainer) hoặc dây đai ở ngang ngực.', 'Đứng quay mặt vào điểm neo, nắm tay cầm kiểu cầm sấp.', 'Bước chân về phía trước, ngả người ra sau tới khi thân nghiêng.', 'Giữ thân thẳng và siết cơ bụng.', 'Kéo ngực về phía tay cầm, ép hai xương bả vai lại gần nhau.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('iron-cross-stretch', 'iron cross stretch', '{GLUTES,HAMSTRINGS,QUADS}', '{}', ARRAY['Nằm ngửa, hai tay dang ngang sang hai bên.', 'Nâng hai chân lên trần nhà, giữ chân thẳng.', 'Từ từ hạ chân sang một bên, cố gắng chạm sàn bằng bàn chân.', 'Giữ tư thế giãn vài giây, rồi đưa chân về vị trí ban đầu.', 'Lặp lại động tác giãn bên kia.', 'Luân phiên hai bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('isometric-chest-squeeze', 'isometric chest squeeze', '{CHEST,TRICEPS,SHOULDERS}', '{}', ARRAY['Đứng hai chân rộng bằng vai, gối hơi gập.', 'Duỗi thẳng hai tay ra trước, song song với sàn, lòng bàn tay hướng vào nhau.', 'Siết cơ ngực thật mạnh, giữ tay thẳng.', 'Giữ tư thế này vài giây, tập trung co cơ ngực.', 'Thả lỏng và giảm lực siết.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('isometric-wipers', 'isometric wipers', '{CHEST,SHOULDERS,TRICEPS,CORE}', '{}', ARRAY['Bắt đầu nằm ngửa trên thảm hoặc ghế.', 'Duỗi thẳng hai tay sang hai bên, vuông góc với thân.', 'Siết cơ bụng và nâng hai chân khỏi sàn, giữ hai chân khép và thẳng.', 'Từ từ hạ chân sang một bên, cố gắng chạm sàn bằng bàn chân và giữ kiểm soát.', 'Dừng một lúc, rồi dùng cơ bụng nâng chân về vị trí ban đầu.', 'Lặp lại động tác, lần này hạ chân sang bên đối diện.', 'Luân phiên hai bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('jack-burpee', 'jack burpee', '{CARDIO,QUADS,HAMSTRINGS,CALVES,SHOULDERS,TRICEPS,CORE}', '{}', ARRAY['Bắt đầu đứng hai chân rộng bằng vai.', 'Hạ người xuống tư thế squat, đặt hai tay xuống sàn phía trước.', 'Đá chân về sau, tiếp đất ở tư thế chống đẩy.', 'Chống đẩy một lần, hạ ngực sát sàn rồi đẩy người lên.', 'Nhảy đưa hai chân về phía trước, tiếp đất ở tư thế squat.', 'Bật nhảy thật mạnh, vươn hai tay lên trên đầu.', 'Tiếp đất nhẹ và hạ người ngay về tư thế squat để bắt đầu lần tiếp theo.'], '{}', false, false, true),
  ('jack-jump-male', 'jack jump (male)', '{CARDIO,QUADS,CALVES}', '{}', ARRAY['Đứng hai chân khép, hai tay buông thõng hai bên.', 'Nhảy lên, dang rộng hai chân và đưa hai tay qua đầu.', 'Khi tiếp đất, nhanh chóng nhảy về tư thế ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('jackknife-sit-up', 'jackknife sit-up', '{CORE}', '{}', ARRAY['Nằm ngửa, duỗi thẳng chân và đưa hai tay qua đầu.', 'Siết cơ bụng, nâng đồng thời chân và thân trên, với tay về phía ngón chân.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ chân và thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('janda-sit-up', 'janda sit-up', '{CORE,LOWER_BACK}', '{}', ARRAY['Nằm ngửa, gập gối, hai bàn chân đặt chắc trên sàn.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết cơ bụng, từ từ nâng thân trên khỏi sàn, cuộn người về phía trước tới khi thân tạo góc 45 độ.', 'Dừng một lúc ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('jump-rope', 'jump rope', '{CARDIO,CALVES,QUADS,HAMSTRINGS,GLUTES}', '{OTHER}', ARRAY['Cầm tay cầm dây nhảy, lòng bàn tay hướng vào trong.', 'Đứng hai chân rộng bằng vai, gối hơi gập.', 'Vung dây qua đầu và nhảy qua dây khi dây quét tới chân.', 'Tiếp đất nhẹ bằng đầu ngón chân và nhảy tiếp khi dây quay lại.', 'Tiếp tục nhảy trong thời gian hoặc số lần mong muốn.'], '{}', false, false, true),
  ('jump-squat', 'jump squat', '{GLUTES,QUADS,HAMSTRINGS,CALVES}', '{}', ARRAY['Đứng hai chân rộng bằng vai.', 'Gập gối, đẩy hông ra sau để hạ người xuống tư thế squat.', 'Bật nhảy thật mạnh khỏi sàn, duỗi hông, gối và cổ chân.', 'Khi đang ở giữa không trung, nhanh chóng đưa tay về phía trước để giữ thăng bằng.', 'Tiếp đất nhẹ bằng đầu ngón chân và vào ngay lần tiếp theo.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('jump-squat-v-2', 'jump squat v. 2', '{GLUTES,QUADS,HAMSTRINGS,CALVES}', '{}', ARRAY['Đứng hai chân rộng bằng vai.', 'Gập gối, đẩy hông ra sau để hạ người xuống tư thế squat.', 'Bật nhảy thật mạnh, duỗi hết hông và gối.', 'Tiếp đất nhẹ bằng đầu ngón chân và hạ người ngay về tư thế squat.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('kettlebell-advanced-windmill', 'kettlebell advanced windmill', '{CORE,SHOULDERS}', '{KETTLEBELL}', ARRAY['Đứng hai chân rộng hơn vai, mũi bàn chân hơi hướng ra ngoài.', 'Cầm tạ ấm bằng tay phải, tay duỗi thẳng lên trên đầu, lòng bàn tay hướng về phía trước.', 'Xoay bàn chân trái một chút sang phải và dồn trọng lượng sang chân trái.', 'Gập gối trái và gập hông, hạ thân trên về phía bên trái.', 'Giữ tay phải duỗi thẳng trên đầu và mắt nhìn vào tạ ấm.', 'Khi hạ thân trên, để chân phải thẳng ra và bàn chân phải xoay nhẹ.', 'Hạ thân trên tới khi cảm thấy căng đùi sau trái và tay phải hướng xuống sàn.', 'Dừng một lúc, rồi siết cơ bụng và đẩy qua gót chân trái để về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi bên.'], '{}', false, false, true),
  ('kettlebell-alternating-hang-clean', 'kettlebell alternating hang clean', '{FOREARMS,SHOULDERS,UPPER_BACK,CORE}', '{KETTLEBELL}', ARRAY['Đứng hai chân rộng bằng vai, mỗi tay cầm một tạ ấm kiểu cầm sấp.', 'Gập gối nhẹ, cúi người từ hông, giữ lưng thẳng và ngực ưỡn.', 'Để tạ ấm rủ trước người, hai tay duỗi thẳng.', 'Trong một động tác liền mạch, duỗi mạnh hông, nhún vai và kéo tạ lên về phía vai.', 'Khi tạ lên ngang vai, xoay cổ tay và đón tạ ở tư thế rack, lòng bàn tay quay vào trong và tạ nằm bên ngoài cẳng tay.', 'Hạ tạ về vị trí ban đầu rồi lặp lại động tác với tay kia.', 'Tiếp tục luân phiên hai tay đủ số lần mong muốn.'], '{}', false, false, true),
  ('kettlebell-alternating-press', 'kettlebell alternating press', '{SHOULDERS,TRICEPS,CORE}', '{KETTLEBELL}', ARRAY['Đứng hai chân rộng bằng vai, mỗi tay cầm một tạ ấm ngang vai.', 'Đẩy một tạ lên trên đầu, duỗi thẳng hết tay.', 'Hạ tạ về ngang vai.', 'Lặp lại với tay kia.', 'Tiếp tục luân phiên hai tay đủ số lần mong muốn.'], '{}', false, false, true),
  ('kettlebell-alternating-press-on-floor', 'kettlebell alternating press on floor', '{CHEST,SHOULDERS,TRICEPS}', '{KETTLEBELL}', ARRAY['Bắt đầu nằm ngửa trên sàn, gập gối, hai bàn chân đặt chắc trên sàn.', 'Mỗi tay cầm một tạ ấm, lòng bàn tay hướng về phía chân, hai tay duỗi thẳng lên trần nhà.', 'Hạ một tạ xuống về phía vai trong khi giữ tạ kia duỗi thẳng lên.', 'Đẩy tạ đã hạ trở lại vị trí ban đầu, đồng thời hạ tạ kia xuống về phía vai.', 'Tiếp tục luân phiên động tác đẩy với mỗi tạ đủ số lần mong muốn.'], '{}', false, false, true),
  ('kettlebell-alternating-renegade-row', 'kettlebell alternating renegade row', '{UPPER_BACK,CORE,SHOULDERS}', '{KETTLEBELL}', ARRAY['Bắt đầu ở tư thế plank cao, hai tay nắm tạ ấm và hai chân rộng bằng hông.', 'Siết cơ bụng và giữ thân thẳng từ đầu tới gót chân.', 'Kéo một tạ lên về phía ngực, giữ khuỷu tay sát thân.', 'Hạ tạ về vị trí ban đầu rồi lặp lại với tay kia.', 'Tiếp tục luân phiên hai tay đủ số lần mong muốn.'], '{}', false, false, true),
  ('kettlebell-alternating-row', 'kettlebell alternating row', '{UPPER_BACK,BICEPS,FOREARMS}', '{KETTLEBELL}', ARRAY['Đứng hai chân rộng bằng vai, gối hơi gập, mỗi tay cầm một tạ ấm với lòng bàn tay quay vào thân.', 'Gập người từ hông, giữ lưng thẳng và siết cơ bụng.', 'Kéo một tạ lên về phía ngực, giữ khuỷu tay sát thân và ép hai xương bả vai lại gần nhau.', 'Hạ tạ về vị trí ban đầu rồi lặp lại với tay kia.', 'Tiếp tục luân phiên hai tay đủ số lần mong muốn.'], '{}', false, false, true),
