  ('lever-shoulder-press', 'lever shoulder press', '{SHOULDERS,TRICEPS,CHEST}', '{MACHINE}', ARRAY['Chỉnh độ cao ghế rồi ngồi lên máy, lưng tựa vào tựa lưng.', 'Nắm tay cầm kiểu cầm sấp và đặt tay ngang vai.', 'Đẩy tay cầm lên cho đến khi hai tay duỗi thẳng, nhưng không khóa khuỷu.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tay cầm về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
