  ('lever-shoulder-press-v-3', 'lever shoulder press v. 3', '{SHOULDERS,TRICEPS,CHEST}', '{MACHINE}', ARRAY['Chỉnh độ cao ghế và tựa lưng của máy tay đòn đến vị trí thoải mái.', 'Ngồi lên máy, lưng tựa vào tựa lưng và hai bàn chân đặt phẳng trên sàn.', 'Nắm tay cầm kiểu cầm sấp, rộng hơn bằng vai một chút.', 'Đẩy tay cầm lên và ra trước cho đến khi hai tay duỗi thẳng, nhưng không khóa.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ tay cầm về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('lever-shrug', 'lever shrug', '{UPPER_BACK,SHOULDERS}', '{MACHINE}', ARRAY['Chỉnh độ cao ghế rồi ngồi lên máy tay đòn, lưng tựa vào đệm.', 'Nắm tay cầm kiểu cầm sấp và giữ tay thẳng.', 'Giữ lưng thẳng, nhấc vai lên gần tai nhất có thể.', 'Giữ tư thế co trong một nhịp, rồi từ từ hạ vai về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('lever-standing-calf-raise', 'lever standing calf raise', '{CALVES}', '{MACHINE}', ARRAY['Chỉnh máy vừa với chiều cao của bạn, đứng với hai chân rộng bằng vai.', 'Đặt vai dưới đệm và giữ tay cầm để giữ thăng bằng.', 'Nhấc gót chân lên cao nhất có thể bằng cách duỗi cổ chân.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ gót chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('lever-standing-chest-press', 'lever standing chest press', '{CHEST,SHOULDERS,TRICEPS}', '{MACHINE}', ARRAY['Chỉnh độ cao ghế rồi ngồi lên máy với hai bàn chân đặt phẳng trên sàn.', 'Nắm tay cầm kiểu cầm sấp và đặt tay ngang ngực.', 'Đẩy tay cầm về phía trước cho đến khi hai tay duỗi thẳng, giữ khuỷu hơi cong.', 'Dừng một nhịp, rồi từ từ kéo tay cầm về phía ngực và kiểm soát động tác suốt quá trình.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('lever-t-bar-row', 'lever t bar row', '{UPPER_BACK,BICEPS,FOREARMS}', '{MACHINE}', ARRAY['Chỉnh độ cao ghế và vị trí bệ đặt chân cho đúng tư thế.', 'Ngồi lên máy, ngực sát đệm và hai bàn chân đặt phẳng trên bệ chân.', 'Nắm tay cầm kiểu cầm sấp, rộng hơn bằng vai một chút.', 'Giữ lưng thẳng và siết bụng.', 'Kéo tay cầm về phía thân, siết hai xương bả vai lại.', 'Dừng một nhịp ở điểm co cơ tối đa, rồi từ từ thả tay cầm về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('lever-t-bar-reverse-grip-row', 'lever t-bar reverse grip row', '{UPPER_BACK,BICEPS,FOREARMS}', '{MACHINE}', ARRAY['Chỉnh độ cao ghế, ngồi lên máy với ngực sát đệm và hai bàn chân đặt phẳng trên sàn.', 'Nắm tay cầm kiểu cầm sấp, rộng hơn bằng vai một chút.', 'Giữ lưng thẳng và siết bụng.', 'Kéo tay cầm về phía ngực, siết hai xương bả vai lại.', 'Dừng một nhịp ở trên cùng, rồi từ từ thả và duỗi tay về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('lever-triceps-extension', 'lever triceps extension', '{TRICEPS,SHOULDERS}', '{MACHINE}', ARRAY['Chỉnh độ cao ghế rồi ngồi lên máy, lưng tựa vào đệm.', 'Nắm tay cầm kiểu cầm sấp và duỗi thẳng hai tay về phía trước.', 'Giữ cánh tay trên cố định, từ từ hạ tay cầm về phía trán bằng cách gập khuỷu.', 'Dừng một nhịp ở dưới cùng, rồi đẩy tay cầm lên về vị trí ban đầu bằng cách duỗi tay.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('lever-unilateral-row', 'lever unilateral row', '{UPPER_BACK,BICEPS,FOREARMS}', '{MACHINE}', ARRAY['Chỉnh độ cao ghế và ngồi đối diện máy.', 'Nắm tay cầm kiểu cầm sấp và giữ lưng thẳng.', 'Kéo tay cầm về phía thân, siết hai xương bả vai lại.', 'Dừng một nhịp ở đỉnh động tác, rồi từ từ thả và duỗi tay về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('london-bridge', 'london bridge', '{UPPER_BACK,SHOULDERS,BICEPS,FOREARMS}', '{OTHER}', ARRAY['Gắn dây vào điểm neo ở trên cao.', 'Đứng quay lưng lại điểm neo, hai chân rộng bằng vai.', 'Nắm dây kiểu cầm sấp, lòng bàn tay hướng xuống.', 'Nghiêng người về phía trước một chút, giữ lưng thẳng và siết bụng.', 'Kéo dây về phía thân, siết hai xương bả vai lại.', 'Dừng một nhịp ở đỉnh động tác, rồi từ từ nhả lực căng và trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('lower-back-curl', 'lower back curl', '{LOWER_BACK,GLUTES,HAMSTRINGS}', '{}', ARRAY['Nằm sấp, duỗi thẳng hai chân và đặt hai tay sát thân.', 'Siết mông và đùi sau, từ từ nhấc thân trên khỏi sàn, cong lưng lên.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('lunge-with-jump', 'lunge with jump', '{GLUTES,QUADS,HAMSTRINGS,CALVES}', '{}', ARRAY['Bắt đầu bằng tư thế đứng, hai chân rộng bằng vai.', 'Bước chân phải về phía trước, hạ người xuống tư thế lunge.', 'Đẩy chân phải và nhảy lên không, đổi vị trí hai chân giữa không trung.', 'Tiếp đất nhẹ với chân trái ở trước, rồi hạ người ngay xuống tư thế lunge.', 'Tiếp tục xen kẽ giữa lunge và nhảy đến đủ số lần mong muốn.'], '{}', false, false, true),
  ('lunge-with-twist', 'lunge with twist', '{CORE,QUADS,GLUTES,HAMSTRINGS}', '{}', ARRAY['Bắt đầu bằng tư thế đứng, hai chân rộng bằng vai.', 'Bước chân phải về phía trước, hạ người xuống tư thế lunge.', 'Khi lunge, xoay thân trên sang phải, đưa khuỷu tay trái về phía đầu gối phải.', 'Dừng một nhịp, rồi trở về vị trí ban đầu.', 'Lặp lại ở bên kia, bước chân trái về phía trước và xoay thân trên sang trái.', 'Tiếp tục xen kẽ hai bên đến đủ số lần mong muốn.'], '{}', false, false, true),
  ('lying-side-quads-stretch', 'lying (side) quads stretch', '{QUADS,HAMSTRINGS}', '{}', ARRAY['Nằm nghiêng, duỗi thẳng hai chân.', 'Gập chân trên và dùng tay nắm mắt cá hoặc bàn chân.', 'Kéo nhẹ mắt cá hoặc bàn chân về phía mông cho đến khi cảm thấy căng ở đùi trước.', 'Giữ tư thế giãn trong 20-30 giây.', 'Thả ra và lặp lại ở bên kia.'], '{}', false, false, true),
  ('lying-elbow-to-knee', 'lying elbow to knee', '{CORE,LOWER_BACK}', '{}', ARRAY['Nằm ngửa, gập gối và đặt hai bàn chân phẳng trên sàn.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết bụng và nhấc thân trên khỏi sàn, đưa khuỷu tay phải về phía đầu gối trái.', 'Đồng thời duỗi thẳng chân phải và nhấc lên khỏi sàn.', 'Dừng một nhịp, rồi trở về vị trí ban đầu.', 'Lặp lại động tác, lần này đưa khuỷu tay trái về phía đầu gối phải và duỗi chân trái.', 'Tiếp tục xen kẽ hai bên đến đủ số lần mong muốn.'], '{}', false, false, true),
  ('lying-leg-raise-flat-bench', 'lying leg raise flat bench', '{CORE}', '{BENCH}', ARRAY['Nằm ngửa trên ghế tập phẳng, lưng ép sát vào ghế.', 'Đặt hai tay dưới mông để đỡ.', 'Giữ hai chân thẳng và khép lại, nhấc lên hướng về trần nhà.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('lying-leg-hip-raise', 'lying leg-hip raise', '{CORE}', '{}', ARRAY['Nằm ngửa, duỗi thẳng hai chân và đặt hai tay sát thân.', 'Đặt hai tay dưới mông để đỡ.', 'Siết bụng và nhấc hai chân khỏi sàn, hướng về trần nhà.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('machine-inner-chest-press', 'machine inner chest press', '{CHEST,TRICEPS,SHOULDERS}', '{MACHINE}', ARRAY['Chỉnh độ cao ghế và ngồi lên máy, lưng dán phẳng vào đệm.', 'Nắm tay cầm kiểu cầm sấp và đặt khuỷu tay tạo góc 90 độ.', 'Đẩy tay cầm về phía trước cho đến khi hai tay duỗi thẳng, thở ra trong lúc đẩy.', 'Dừng một nhịp ở cuối động tác, rồi từ từ trở về vị trí ban đầu và hít vào.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('march-sit-wall', 'march sit (wall)', '{GLUTES,QUADS,HAMSTRINGS,CALVES}', '{}', ARRAY['Đứng lưng dựa tường, hai chân rộng bằng hông.', 'Từ từ trượt lưng xuống tường cho đến khi đầu gối gập góc 90 độ.', 'Nhấc chân phải khỏi sàn và đưa đầu gối về phía ngực.', 'Hạ chân phải xuống, rồi nhấc chân trái khỏi sàn và đưa đầu gối về phía ngực.', 'Tiếp tục xen kẽ nhấc chân phải và chân trái đến đủ số lần mong muốn.'], '{}', false, false, true),
  ('medicine-ball-catch-and-overhead-throw', 'medicine ball catch and overhead throw', '{LATS,SHOULDERS,CORE}', '{BALL}', ARRAY['Đứng hai chân rộng bằng vai, hai tay cầm bóng medicine ngang ngực.', 'Hơi khuỵu gối và siết bụng.', 'Hạ người xuống tư thế squat, giữ lưng thẳng và ngực ưỡn.', 'Bùng nổ duỗi hông và chân, đồng thời ném bóng medicine qua đầu.', 'Buông bóng ở trên cùng của động tác, rồi bắt lại khi bóng rơi xuống.', 'Hạ người về tư thế squat và lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('medicine-ball-chest-pass', 'medicine ball chest pass', '{CHEST,SHOULDERS,TRICEPS}', '{BALL}', ARRAY['Đứng hai chân rộng bằng vai, cầm bóng medicine ngang ngực.', 'Duỗi thẳng hai tay về phía trước, đẩy bóng ra khỏi ngực thật mạnh.', 'Khi buông bóng, theo đà với hai tay và thân người, chuyển trọng lượng từ chân sau sang chân trước.', 'Bắt bóng khi nảy lại từ tường hoặc đồng đội, rồi lặp lại động tác ngay.', 'Tiếp tục đến đủ số lần mong muốn.'], '{}', false, false, true),
  ('medicine-ball-chest-push-from-3-point-stance', 'medicine ball chest push from 3 point stance', '{CHEST,SHOULDERS,TRICEPS}', '{BALL}', ARRAY['Vào tư thế 3 điểm chống, một tay cầm bóng medicine, tay kia chống xuống sàn.', 'Duỗi chân và giữ cơ thể thành một đường thẳng.', 'Hạ ngực về phía sàn, giữ lưng thẳng.', 'Đẩy bóng ra xa khỏi thân, duỗi thẳng hết cánh tay.', 'Trở về vị trí ban đầu và lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('medicine-ball-chest-push-multiple-response', 'medicine ball chest push multiple response', '{CHEST,TRICEPS,SHOULDERS}', '{BALL}', ARRAY['Đứng hai chân rộng bằng vai, cầm bóng medicine ngang ngực.', 'Duỗi thẳng hai tay về phía trước, đẩy bóng ra khỏi ngực.', 'Dừng một nhịp, rồi từ từ đưa bóng về sát ngực.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('medicine-ball-chest-push-single-response', 'medicine ball chest push single response', '{CHEST,TRICEPS,SHOULDERS}', '{BALL}', ARRAY['Đứng hai chân rộng bằng vai, cầm bóng medicine ngang ngực.', 'Duỗi thẳng hai tay về phía trước, đẩy bóng ra khỏi ngực.', 'Dừng một nhịp, rồi từ từ đưa bóng về sát ngực.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO exercises (slug, name_en, muscle_groups, equipment, steps_vi, mistakes_vi, analyzable, is_active, is_draft) VALUES
  ('medicine-ball-chest-push-with-run-release', 'medicine ball chest push with run release', '{CHEST,TRICEPS,SHOULDERS,CORE}', '{BALL}', ARRAY['Đứng hai chân rộng bằng vai, cầm bóng medicine ngang ngực.', 'Bước chân phải về phía trước và đồng thời đẩy bóng về phía trước, duỗi thẳng hết hai tay.', 'Khi đẩy bóng, buông bóng và để bóng lăn về phía trước.', 'Nhanh chóng chạy về phía trước và bắt bóng trước khi bóng chạm đất.', 'Khi bắt được bóng, đưa về sát ngực và lặp lại động tác với chân trái ở trước.', 'Tiếp tục xen kẽ hai chân và lặp lại bài tập đến đủ số lần mong muốn.'], '{}', false, false, true),
  ('medicine-ball-close-grip-push-up', 'medicine ball close grip push up', '{TRICEPS,CHEST,SHOULDERS}', '{BALL}', ARRAY['Vào tư thế plank cao, hai tay đặt trên bóng medicine, rộng bằng vai.', 'Hạ người về phía sàn bằng cách gập khuỷu tay, giữ khuỷu sát thân.', 'Đẩy lên về vị trí ban đầu, duỗi thẳng hết hai tay.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('medicine-ball-overhead-slam', 'medicine ball overhead slam', '{UPPER_BACK,SHOULDERS,CORE}', '{BALL}', ARRAY['Đứng hai chân rộng bằng vai, hai tay giơ bóng medicine lên trên đầu.', 'Siết bụng và giữ lưng thẳng.', 'Hơi khuỵu gối và đập mạnh bóng medicine xuống sàn phía trước.', 'Khi đập bóng, dùng toàn bộ cơ thể để tạo lực, kể cả vai và bụng.', 'Bắt bóng khi nảy lên và lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('medicine-ball-supine-chest-throw', 'medicine ball supine chest throw', '{TRICEPS,CHEST,SHOULDERS}', '{BALL}', ARRAY['Nằm ngửa trên ghế, gập gối và đặt hai bàn chân phẳng trên sàn.', 'Cầm bóng medicine bằng hai tay, duỗi thẳng hai tay lên phía trên ngực.', 'Hạ bóng medicine về phía ngực, giữ khuỷu tay sát thân.', 'Đẩy bóng lên mạnh mẽ, duỗi thẳng hết hai tay và ném bóng cao nhất có thể.', 'Bắt bóng medicine và lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('mixed-grip-chin-up', 'mixed grip chin-up', '{LATS,BICEPS,FOREARMS}', '{}', ARRAY['Nắm xà kéo bằng kiểu cầm ngửa (lòng bàn tay hướng vào người), hai tay rộng hơn bằng vai một chút.', 'Treo người trên xà với hai tay duỗi thẳng và hai chân rời khỏi sàn.', 'Siết cơ lưng và kéo người lên về phía xà, dẫn bằng ngực.', 'Tiếp tục kéo cho đến khi cằm vượt qua xà.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ người xuống vị trí ban đầu có kiểm soát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('modified-hindu-push-up-male', 'modified hindu push-up (male)', '{CHEST,TRICEPS,SHOULDERS,CORE}', '{}', ARRAY['Vào tư thế chống đẩy, hai tay rộng hơn bằng vai một chút và hai chân rộng bằng hông.', 'Hạ người về phía sàn bằng cách gập khuỷu tay và giữ bụng siết chặt.', 'Khi hạ người, dồn trọng lượng ra sau và nhấc hông lên về phía trần nhà, tạo hình chữ V ngược với cơ thể.', 'Tiếp tục hạ người cho đến khi ngực vừa chạm sàn, rồi đảo ngược động tác: đẩy hông xuống lại và duỗi thẳng tay để về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('modified-push-up-to-lower-arms', 'modified push up to lower arms', '{FOREARMS,TRICEPS,CHEST,SHOULDERS}', '{}', ARRAY['Vào tư thế chống đẩy, hai tay đặt ngay dưới vai và cơ thể thẳng hàng.', 'Hạ người về phía sàn bằng cách gập khuỷu tay, giữ khuỷu sát thân.', 'Khi khuỷu tay gập 90 độ, hạ cẳng tay xuống sàn, giữ khuỷu ngay dưới vai.', 'Dừng một nhịp, rồi đẩy qua lòng bàn tay để nâng cẳng tay trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
