  ('pike-to-cobra-push-up', 'pike-to-cobra push-up', '{GLUTES,CORE,SHOULDERS,TRICEPS}', '{}', ARRAY['Vào tư thế chống đẩy, hai tay rộng hơn bằng vai một chút và hai chân khép lại.', 'Siết bụng và nhấc hông lên về phía trần nhà, tạo hình chữ V ngược với cơ thể.', 'Hạ thân trên về phía sàn bằng cách gập khuỷu tay, giữ khuỷu sát thân.', 'Khi hạ xuống, dồn trọng lượng về phía trước và chuyển sang tư thế cobra bằng cách duỗi thẳng tay và nâng ngực lên.', 'Đảo ngược động tác bằng cách gập khuỷu tay và hạ ngực xuống lại về phía sàn.', 'Đẩy qua hai tay để trở về tư thế chữ V ngược.', 'Tiếp tục động tác bằng cách hạ hông xuống lại về phía sàn, trở về tư thế chống đẩy ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('plyo-push-up', 'plyo push up', '{CHEST,TRICEPS,SHOULDERS,CORE}', '{}', ARRAY['Vào tư thế plank cao, hai tay rộng hơn bằng vai một chút.', 'Hạ ngực về phía sàn bằng cách gập khuỷu tay, giữ cơ thể thẳng hàng.', 'Bật mạnh khỏi sàn, dùng cơ ngực để đẩy thân trên rời khỏi sàn.', 'Tiếp đất nhẹ với hai tay trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('posterior-step-to-overhead-reach', 'posterior step to overhead reach', '{CORE,GLUTES,HAMSTRINGS,QUADS,SHOULDERS}', '{}', ARRAY['Đứng hai chân rộng bằng hông, hai tay buông thẳng bên thân.', 'Bước chân phải lùi về sau, tiếp đất bằng phần trước bàn chân.', 'Gập đầu gối trái và hạ người xuống tư thế lunge.', 'Khi hạ xuống lunge, đồng thời đưa hai tay qua đầu.', 'Dừng một nhịp ở dưới cùng của lunge, rồi trở về vị trí ban đầu bằng cách đẩy qua gót chân trái và kéo chân phải về phía trước.', 'Lặp lại động tác ở bên kia, bước chân trái lùi về sau và gập đầu gối phải.', 'Tiếp tục xen kẽ hai bên đến đủ số lần mong muốn.'], '{}', false, false, true),
  ('posterior-tibialis-stretch', 'posterior tibialis stretch', '{CALVES,HAMSTRINGS,QUADS}', '{OTHER}', ARRAY['Ngồi trên sàn, duỗi thẳng hai chân về phía trước.', 'Quàng dây quanh phần trước bàn chân và nắm hai đầu dây bằng tay.', 'Kéo nhẹ dây về phía mình, gập bàn chân và giãn cơ bắp chân.', 'Giữ tư thế giãn trong 20-30 giây.', 'Nhả lực căng trên dây và thả lỏng bàn chân.', 'Lặp lại động tác giãn ở chân kia.'], '{}', false, false, true),
  ('potty-squat', 'potty squat', '{CORE,QUADS,GLUTES}', '{}', ARRAY['Đứng hai chân rộng bằng vai, mũi chân hơi hướng ra ngoài.', 'Hạ người bằng cách gập gối và đẩy hông ra sau, như đang ngồi xuống ghế.', 'Giữ ngực ưỡn và lưng thẳng trong suốt động tác.', 'Hạ người cho đến khi đùi song song với sàn hoặc thấp nhất có thể một cách thoải mái.', 'Dừng một nhịp ở dưới cùng, rồi đẩy qua gót chân để trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('potty-squat-with-support', 'potty squat with support', '{GLUTES,QUADS,HAMSTRINGS,CALVES}', '{}', ARRAY['Đứng hai chân rộng bằng vai, mũi chân hơi hướng ra ngoài.', 'Vịn vào chỗ tựa vững chắc như ghế hoặc tường để giữ thăng bằng.', 'Hạ người xuống tư thế squat bằng cách gập gối và đẩy hông ra sau.', 'Giữ ngực ưỡn và lưng thẳng trong suốt động tác.', 'Dừng một nhịp ở dưới cùng, rồi đẩy qua gót chân để trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('power-clean', 'power clean', '{HAMSTRINGS,GLUTES,QUADS,CALVES}', '{BARBELL_RACK}', ARRAY['Bắt đầu với tạ đòn đặt trên sàn trước mặt, hai chân rộng bằng vai.', 'Cúi xuống và nắm tạ đòn kiểu cầm sấp, rộng hơn bằng vai một chút.', 'Giữ lưng thẳng và ngực ưỡn khi nhấc tạ đòn khỏi sàn, duỗi hông và gối.', 'Khi tạ đòn lên đến giữa đùi, bùng nổ kéo tạ lên, nhún vai và đưa khuỷu tay lên cao và sang hai bên.', 'Khi tạ đòn lên đến điểm cao nhất, nhanh chóng luồn người xuống dưới, xoay khuỷu tay và đỡ tạ đòn trên vai ở tư thế front squat.', 'Đứng dậy với tạ đòn, duỗi thẳng hết hông và gối.', 'Hạ tạ đòn về vị trí ban đầu, giữ kiểm soát tạ suốt động tác.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('power-point-plank', 'power point plank', '{CORE,SHOULDERS,TRICEPS,GLUTES}', '{}', ARRAY['Vào tư thế plank cao, hai tay đặt ngay dưới vai và cơ thể thẳng hàng từ đầu đến chân.', 'Siết bụng và siết mông để giữ tư thế ổn định.', 'Hạ người xuống cẳng tay, từng tay một, và giữ cơ thể thẳng hàng từ đầu đến chân.', 'Giữ tư thế này trong thời gian mong muốn, và siết bụng và mông suốt quá trình.', 'Để trở về vị trí ban đầu, đẩy qua cẳng tay và nâng người trở lại vào tư thế plank cao.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('prisoner-half-sit-up-male', 'prisoner half sit-up (male)', '{CORE}', '{}', ARRAY['Nằm ngửa, gập gối và đặt hai bàn chân phẳng trên sàn.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết bụng, từ từ nhấc thân trên khỏi sàn và cuộn người về phía trước cho đến khi thân tạo góc 45 độ.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('prone-twist-on-stability-ball', 'prone twist on stability ball', '{CORE,LOWER_BACK}', '{BALL}', ARRAY['Bắt đầu bằng cách nằm sấp trên bóng tập, hai chân rộng bằng vai và mũi chân chạm sàn.', 'Đặt hai tay sau đầu hoặc khoanh trước ngực.', 'Siết cơ bụng và từ từ nhấc thân trên khỏi bóng, giữ lưng thẳng.', 'Xoay thân sang một bên, đưa vai về phía hông. Giữ hông và chân ổn định trong suốt động tác.', 'Dừng một nhịp, rồi trở về vị trí ban đầu.', 'Lặp lại xoay sang bên kia.', 'Tiếp tục xen kẽ hai bên đến đủ số lần mong muốn.'], '{}', false, false, true),
  ('pull-up-neutral-grip', 'pull up (neutral grip)', '{LATS,BICEPS,FOREARMS}', '{}', ARRAY['Treo người trên xà kéo, kiểu cầm trung tính (hai lòng bàn tay hướng vào nhau) và hai tay duỗi thẳng.', 'Siết bụng và siết hai xương bả vai lại.', 'Kéo người lên về phía xà bằng cách gập khuỷu tay và đưa khuỷu tay xuống về phía hông.', 'Tiếp tục kéo cho đến khi cằm vượt qua xà.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ người về vị trí ban đầu có kiểm soát.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('pull-in-on-stability-ball', 'pull-in (on stability ball)', '{CORE}', '{BALL}', ARRAY['Bắt đầu bằng cách ngồi trên bóng tập, hai bàn chân đặt phẳng trên sàn và đầu gối gập 90 độ.', 'Đặt hai tay hai bên bóng để đỡ.', 'Siết bụng và từ từ lăn hông về phía trước, đưa đầu gối về phía ngực.', 'Dừng một nhịp ở trên cùng của động tác, rồi từ từ duỗi chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
