  ('quarter-sit-up', 'quarter sit-up', '{CORE}', '{}', ARRAY['Nằm ngửa, gập gối và đặt hai bàn chân phẳng trên sàn.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết bụng, từ từ nhấc thân trên khỏi sàn và cuộn người về phía trước cho đến khi thân tạo góc 45 độ.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('quick-feet-v-2', 'quick feet v. 2', '{QUADS,CALVES,HAMSTRINGS}', '{}', ARRAY['Đứng hai chân rộng bằng vai, hai tay buông thẳng bên thân.', 'Bắt đầu nhấc chân lên xuống thật nhanh, như đang chạy tại chỗ.', 'Giữ động tác nhanh và nhẹ, tập trung đứng bằng phần trước bàn chân.', 'Tiếp tục trong thời gian hoặc số lần mong muốn.'], '{}', false, false, true),
  ('raise-single-arm-push-up', 'raise single arm push-up', '{CHEST,TRICEPS,SHOULDERS,CORE}', '{}', ARRAY['Vào tư thế chống đẩy, hai tay rộng hơn bằng vai một chút và hai chân khép lại.', 'Duỗi một tay thẳng ra ngang, song song với sàn.', 'Hạ người về phía sàn bằng cách gập khuỷu tay, giữ lưng thẳng và siết bụng.', 'Đẩy người lên về vị trí ban đầu, dùng cơ ngực để nâng cơ thể.', 'Lặp lại với tay kia duỗi ra.'], '{}', false, false, true),
  ('rear-decline-bridge', 'rear decline bridge', '{GLUTES,HAMSTRINGS,LOWER_BACK}', '{BENCH}', ARRAY['Nằm ngửa, đặt hai bàn chân phẳng trên sàn và gập gối.', 'Đặt hai tay sát thân, lòng bàn tay hướng xuống.', 'Siết mông và đùi sau, nhấc hông khỏi sàn cho đến khi cơ thể thành một đường thẳng từ đầu gối tới vai.', 'Giữ tư thế này vài giây, rồi từ từ hạ hông về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('rear-deltoid-stretch', 'rear deltoid stretch', '{SHOULDERS,UPPER_BACK}', '{}', ARRAY['Đứng thẳng, hai chân rộng bằng vai.', 'Đưa tay phải qua trước ngực, đặt tay trái lên khuỷu tay phải.', 'Kéo nhẹ tay phải về phía vai trái, cảm nhận căng ở vai phải.', 'Giữ tư thế giãn trong 15-30 giây, rồi thả ra.', 'Lặp lại ở bên kia.'], '{}', false, false, true),
  ('rear-pull-up', 'rear pull-up', '{LATS,BICEPS,FOREARMS}', '{}', ARRAY['Nắm xà kéo kiểu cầm sấp, rộng hơn bằng vai một chút.', 'Treo người trên xà, hai tay duỗi thẳng và cơ thể thẳng.', 'Siết cơ lưng và kéo người lên về phía xà, giữ khuỷu sát thân.', 'Tiếp tục kéo cho đến khi cằm vượt qua xà.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('reclining-big-toe-pose-with-rope', 'reclining big toe pose with rope', '{HAMSTRINGS,CALVES,GLUTES}', '{OTHER}', ARRAY['Nằm ngửa, duỗi thẳng hai chân và đặt hai tay sát thân.', 'Quàng dây quanh phần trước bàn chân phải và nắm hai đầu dây bằng tay.', 'Từ từ nâng chân phải về phía ngực, giữ đầu gối thẳng và mũi chân gập.', 'Giữ tư thế giãn vài giây, rồi từ từ hạ chân về vị trí ban đầu.', 'Lặp lại với chân trái.', 'Tiếp tục xen kẽ hai chân đến đủ số lần mong muốn.'], '{}', false, false, true),
  ('resistance-band-hip-thrusts-on-knees-female', 'resistance band hip thrusts on knees (female)', '{GLUTES,HAMSTRINGS,QUADS}', '{BAND}', ARRAY['Bắt đầu bằng cách quỳ trên sàn, hai đầu gối rộng bằng hông và hai bàn chân gập.', 'Quấn dây kháng lực quanh đùi, ngay phía trên đầu gối.', 'Đặt hai tay lên hông hoặc duỗi ra trước để giữ thăng bằng.', 'Siết mông và cơ bụng.', 'Đẩy hông về phía trước và siết mông khi nhấc đầu gối khỏi sàn, duỗi hông cho đến khi đùi song song với sàn.', 'Giữ tư thế một nhịp, rồi từ từ hạ đầu gối về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('resistance-band-leg-extension', 'resistance band leg extension', '{QUADS,HAMSTRINGS}', '{BAND}', ARRAY['Gắn dây kháng lực vào điểm neo chắc chắn và quấn quanh mắt cá chân.', 'Đứng quay mặt về điểm neo, hai chân rộng bằng vai.', 'Giữ cơ bụng siết và thân trên ổn định, duỗi thẳng chân ra trước.', 'Dừng một nhịp ở trên cùng, rồi từ từ đưa chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi chân.'], '{}', false, false, true),
