  ('side-push-neck-stretch', 'side push neck stretch', '{UPPER_BACK}', '{}', ARRAY['Đứng hoặc ngồi thẳng lưng, thả lỏng vai.', 'Nghiêng đầu sang phải, đưa tai phải về phía vai phải.', 'Đặt tay phải lên phía trái đầu và ấn nhẹ để tăng độ giãn.', 'Giữ tư thế giãn trong 15-30 giây.', 'Lặp lại ở bên kia, nghiêng đầu sang trái và ấn bằng tay trái.', 'Lặp lại động tác giãn 2-3 lần ở mỗi bên.'], '{}', false, false, true),
  ('side-push-up', 'side push-up', '{TRICEPS,SHOULDERS,CHEST,CORE}', '{}', ARRAY['Bắt đầu bằng cách nằm nghiêng, duỗi thẳng hai chân và xếp chồng lên nhau.', 'Đặt tay dưới xuống sàn ngay dưới vai, các ngón tay hướng về phía trước.', 'Ấn qua tay dưới để nhấc người khỏi sàn, giữ chân thẳng và siết bụng.', 'Duỗi tay trên thẳng lên trần nhà, tạo đường thẳng từ đầu đến gót chân.', 'Hạ người về vị trí ban đầu có kiểm soát.', 'Lặp lại đủ số lần mong muốn, rồi đổi bên.'], '{}', false, false, true),
  ('side-wrist-pull-stretch', 'side wrist pull stretch', '{FOREARMS}', '{}', ARRAY['Đứng hai chân rộng bằng vai, hai tay duỗi trước người.', 'Duỗi tay phải sang ngang, song song với sàn, lòng bàn tay hướng xuống.', 'Dùng tay trái nắm tay phải và kéo nhẹ về phía thân, cảm nhận căng ở cẳng tay phải.', 'Giữ tư thế giãn trong 15-30 giây, rồi thả ra.', 'Lặp lại ở bên kia.'], '{}', false, false, true),
  ('side-to-side-chin', 'side-to-side chin', '{LATS,BICEPS,FOREARMS}', '{}', ARRAY['Đứng hai chân rộng bằng vai, hơi khuỵu gối.', 'Nắm xà kéo kiểu cầm sấp, hai tay rộng hơn bằng vai một chút.', 'Treo người trên xà, hai tay duỗi thẳng và cơ thể thả lỏng.', 'Kéo người lên bằng cách gập khuỷu tay và đưa cằm về phía xà, giữ cơ thể thẳng.', 'Khi cằm vượt qua xà, hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
