  ('smith-sumo-squat', 'smith sumo squat', '{GLUTES,QUADS,HAMSTRINGS,CALVES}', '{MACHINE}', ARRAY['Chỉnh thanh tạ máy Smith ngang hông.', 'Đứng hai chân rộng hơn vai, mũi chân hướng ra ngoài.', 'Đứng dưới thanh tạ, đặt lên lưng trên và cơ vai.', 'Siết bụng và giữ ngực ngẩng khi hạ người xuống tư thế squat, đẩy hông ra sau và gập gối.', 'Hạ tới khi đùi song song sàn, hoặc thấp nhất có thể thoải mái.', 'Dừng một nhịp ở dưới cùng, rồi đẩy gót chân để về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('smith-toe-raise', 'smith toe raise', '{CALVES}', '{MACHINE}', ARRAY['Chỉnh thanh tạ máy Smith đến độ cao cho phép bạn đứng thoải mái với hai bàn chân phẳng trên sàn.', 'Đặt mình dưới thanh tạ với vai thẳng dưới thanh, hai chân rộng bằng vai.', 'Đặt phần đệm bàn chân lên bệ nâng hoặc đĩa tạ, gót chân thõng ra khỏi mép.', 'Nắm thanh tạ kiểu cầm sấp, rộng hơn vai một chút.', 'Siết bụng và giữ lưng thẳng suốt bài tập.', 'Từ từ nhấc gót chân lên cao nhất có thể, nâng trọng lượng cơ thể lên phần đệm bàn chân.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ gót chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('smith-upright-row', 'smith upright row', '{SHOULDERS,UPPER_BACK,BICEPS}', '{MACHINE}', ARRAY['Đứng hai chân rộng bằng vai, đối diện máy Smith.', 'Nắm thanh tạ kiểu cầm sấp, rộng hơn vai một chút.', 'Giữ lưng thẳng và siết bụng.', 'Kéo thanh tạ lên về phía cằm, dẫn dắt bằng khuỷu tay.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thanh tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO exercises (slug, name_en, muscle_groups, equipment, steps_vi, mistakes_vi, analyzable, is_active, is_draft) VALUES
  ('smith-wide-grip-bench-press', 'smith wide grip bench press', '{CHEST,TRICEPS,SHOULDERS}', '{MACHINE,BENCH}', ARRAY['Chỉnh ghế tập đến vị trí thoải mái trên máy Smith.', 'Nằm lên ghế, hai chân đặt phẳng trên sàn.', 'Nắm thanh tạ kiểu cầm rộng, rộng hơn vai một chút.', 'Mở khóa thanh tạ và hạ chậm về phía ngực, giữ khuỷu tay mở sang hai bên.', 'Dừng một nhịp khi thanh tạ chạm ngực.', 'Đẩy thanh tạ về vị trí ban đầu, duỗi thẳng hai tay.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('smith-wide-grip-decline-bench-press', 'smith wide grip decline bench press', '{CHEST,TRICEPS,SHOULDERS}', '{MACHINE,BENCH}', ARRAY['Chỉnh ghế dốc xuống đến góc mong muốn.', 'Nằm lên ghế, đặt hai chân vào đệm chân dưới.', 'Nắm thanh tạ kiểu cầm rộng, rộng hơn vai một chút.', 'Mở khóa thanh tạ và hạ chậm về phía ngực, giữ khuỷu tay hướng ra ngoài.', 'Dừng một nhịp khi thanh tạ chạm ngực.', 'Đẩy thanh tạ về vị trí ban đầu, duỗi thẳng hai tay.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('snatch-pull', 'snatch pull', '{QUADS,HAMSTRINGS,GLUTES,CALVES}', '{BARBELL_RACK}', ARRAY['Đứng hai chân rộng bằng vai, thanh tạ đặt trên sàn trước mặt.', 'Gập gối và gập hông để hạ người xuống tư thế squat, nắm thanh tạ kiểu cầm sấp.', 'Giữ lưng thẳng và ngực ngẩng khi đẩy qua gót chân để nhấc thanh tạ khỏi sàn, duỗi hông và gối.', 'Khi thanh tạ lên ngang hông, kéo mạnh thanh tạ lên, nhún vai và đưa khuỷu tay lên cao, sang hai bên.', 'Khi thanh tạ lên điểm cao nhất, nhanh chóng chui xuống dưới thanh tạ, hạ người xuống tư thế squat sâu.', 'Đón thanh tạ phía trên đầu với hai tay duỗi thẳng và gối gập.', 'Đứng dậy bằng cách duỗi hông và gối, giữ thanh tạ trên đầu.', 'Hạ thanh tạ về vị trí ban đầu bằng cách làm ngược lại chuyển động.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('spell-caster', 'spell caster', '{CORE,LOWER_BACK}', '{DUMBBELL}', ARRAY['Đứng hai chân rộng bằng vai, cầm một tạ đơn bằng một tay.', 'Hơi gập gối và gập hông về trước, giữ lưng thẳng.', 'Duỗi cánh tay cầm tạ về phía bàn chân đối diện, xoay thân trên khi làm vậy.', 'Trở về vị trí ban đầu và lặp lại bên kia.', 'Tiếp tục đổi bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('sphinx', 'sphinx', '{LOWER_BACK,GLUTES,HAMSTRINGS}', '{}', ARRAY['Nằm sấp, hai cẳng tay đặt phẳng trên sàn, khuỷu tay nằm ngay dưới vai.', 'Siết bụng và nâng ngực khỏi sàn, giữ cẳng tay và mũi chân trên sàn.', 'Giữ tư thế vài giây, đảm bảo cổ ở vị trí trung tính.', 'Từ từ hạ ngực về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('spider-crawl-push-up', 'spider crawl push up', '{GLUTES,CORE,CHEST,SHOULDERS}', '{}', ARRAY['Bắt đầu ở tư thế chống đẩy, hai tay rộng hơn vai một chút và hai chân khép lại.', 'Đưa đầu gối phải về phía khuỷu tay phải, giữ đầu gối cách sàn.', 'Khi đưa đầu gối phải về, đồng thời hạ thân xuống sàn bằng cách gập khuỷu tay.', 'Đẩy người lên về vị trí ban đầu, rồi lặp lại với đầu gối trái hướng về khuỷu tay trái.', 'Tiếp tục đổi bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('spine-stretch', 'spine stretch', '{LOWER_BACK,HAMSTRINGS,GLUTES}', '{}', ARRAY['Ngồi trên sàn, hai chân duỗi thẳng trước người.', 'Đặt hai tay ra sau người trên sàn, các ngón tay hướng về phía thân.', 'Siết bụng và từ từ ngả người ra sau, giữ lưng thẳng.', 'Tiếp tục ngả người ra sau cho tới khi cảm thấy căng ở cột sống.', 'Giữ tư thế kéo giãn vài giây, rồi từ từ trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('spine-twist', 'spine twist', '{CORE,LOWER_BACK}', '{}', ARRAY['Ngồi trên sàn, hai chân duỗi thẳng trước người.', 'Gập gối và đặt hai bàn chân phẳng trên sàn, rộng bằng hông.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết cơ bụng và từ từ xoay thân trên sang phải, đưa khuỷu tay phải về phía đầu gối trái.', 'Dừng một nhịp ở cuối động tác xoay, rồi từ từ trở về vị trí ban đầu.', 'Lặp lại động tác xoay sang trái, đưa khuỷu tay trái về phía đầu gối phải.', 'Tiếp tục đổi bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('split-squats', 'split squats', '{QUADS,GLUTES,HAMSTRINGS,CALVES}', '{}', ARRAY['Đứng hai chân rộng bằng vai.', 'Bước một chân về phía trước, đặt cách chân còn lại khoảng hai feet.', 'Hạ người bằng cách gập gối và hông, giữ lưng thẳng.', 'Hạ tới khi đùi trước song song sàn, còn đầu gối sau lơ lửng ngay trên sàn.', 'Dừng một nhịp, rồi đẩy gót chân trước để về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn, rồi đổi chân và làm lại.'], '{}', false, false, true),
  ('squat-jerk', 'squat jerk', '{QUADS,GLUTES,HAMSTRINGS,CALVES,CORE}', '{BARBELL_RACK}', ARRAY['Bắt đầu với thanh tạ đặt trên vai, hai chân rộng bằng vai.', 'Hạ người xuống tư thế squat, giữ ngực ngẩng và đầu gối đi theo hướng mũi chân.', 'Khi xuống tới đáy squat, bùng nổ đẩy qua chân và đẩy thanh tạ lên qua đầu.', 'Khi thanh tạ lên tới đỉnh, nhanh chóng hạ người vào tư thế tách chân, một chân trước và một chân sau.', 'Đón thanh tạ phía trên đầu với hai tay duỗi thẳng, đầu gối chân sau hơi chạm sàn.', 'Đứng lên từ tư thế tách chân, đưa hai chân về lại với nhau.', 'Hạ thanh tạ về vai và lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('squat-on-bosu-ball', 'squat on bosu ball', '{QUADS,GLUTES,HAMSTRINGS,CALVES}', '{BALL}', ARRAY['Đặt bóng bosu trên sàn, mặt phẳng hướng lên.', 'Đứng hai chân rộng bằng vai và đứng lên trên bóng bosu.', 'Hạ người bằng cách gập gối và hông, như ngồi xuống ghế.', 'Giữ ngực ngẩng và trọng tâm dồn vào gót chân.', 'Hạ tới khi đùi song song sàn.', 'Dừng một nhịp, rồi đẩy gót chân để về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('squat-to-overhead-reach', 'squat to overhead reach', '{QUADS,GLUTES,HAMSTRINGS,CORE}', '{}', ARRAY['Đứng hai chân rộng bằng vai, mũi chân hơi chĩa ra ngoài.', 'Hạ người xuống tư thế squat bằng cách gập gối và đẩy hông ra sau.', 'Khi đứng dậy từ tư thế squat, duỗi hai tay lên cao qua đầu, với về phía trần.', 'Trở về vị trí ban đầu bằng cách hạ tay xuống và gập gối để squat lại.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('squat-to-overhead-reach-with-twist', 'squat to overhead reach with twist', '{QUADS,GLUTES,HAMSTRINGS,CORE}', '{}', ARRAY['Đứng hai chân rộng bằng vai, mũi chân hơi chĩa ra ngoài.', 'Hạ người xuống tư thế squat bằng cách gập gối và đẩy hông ra sau.', 'Khi đứng dậy từ squat, nâng hai tay qua đầu và xoay thân trên sang một bên.', 'Trở về vị trí ban đầu và squat lại, lần này xoay thân trên sang bên đối diện.', 'Tiếp tục đổi bên ở mỗi lần squat.'], '{}', false, false, true),
  ('stability-ball-crunch-full-range-hands-behind-head', 'stability ball crunch (full range hands behind head)', '{CORE}', '{BALL}', ARRAY['Ngồi lên bóng tập, hai chân đặt phẳng trên sàn và gập gối 90 độ.', 'Đặt hai tay sau đầu, khuỷu tay hướng ra ngoài.', 'Siết cơ bụng, từ từ cuộn thân trên về phía trước, đưa ngực về phía đầu gối.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thân trên về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('stalder-press', 'stalder press', '{TRICEPS,SHOULDERS,CORE}', '{}', ARRAY['Bắt đầu bằng cách đứng hai chân rộng bằng vai, hai tay duỗi thẳng qua đầu.', 'Hơi gập gối và siết bụng.', 'Hạ người xuống tư thế squat, giữ hai tay duỗi thẳng qua đầu.', 'Khi squat xuống, ấn hai tay xuống về phía sàn, siết cơ tay sau.', 'Dừng một nhịp ở đáy squat, rồi đẩy gót chân để đứng lên và đồng thời nâng hai tay trở lại qua đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('standing-archer', 'standing archer', '{UPPER_BACK,SHOULDERS,BICEPS,FOREARMS}', '{}', ARRAY['Đứng hai chân rộng bằng vai, hơi gập gối.', 'Duỗi thẳng hai tay ra trước, ngang vai, song song sàn.', 'Xoay thân trên sang phải, giữ hai tay duỗi và lưng thẳng.', 'Khi xoay, duỗi tay phải ra trước và đưa tay trái ra sau, như động tác kéo dây cung.', 'Giữ tư thế vài giây, rồi trở về vị trí ban đầu.', 'Lặp lại động tác, lần này xoay thân trên sang trái và duỗi tay trái ra trước, tay phải ra sau.', 'Tiếp tục đổi bên đủ số lần mong muốn.'], '{}', false, false, true),
  ('standing-behind-neck-press', 'standing behind neck press', '{SHOULDERS,TRICEPS,UPPER_BACK}', '{BARBELL_RACK}', ARRAY['Đứng hai chân rộng bằng vai, cầm thanh tạ sau gáy bằng kiểu cầm sấp.', 'Giữ lưng thẳng và siết bụng.', 'Đẩy thanh tạ lên trên bằng cách duỗi thẳng tay, duỗi hết khuỷu tay.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ thanh tạ về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('standing-calf-raise-on-a-staircase', 'standing calf raise (on a staircase)', '{CALVES}', '{}', ARRAY['Đứng ở mép bậc thang hoặc bục chắc, gót chân thõng ra ngoài và ngón chân đặt trên bậc.', 'Bám vào lan can hoặc tường để giữ thăng bằng nếu cần.', 'Từ từ nhấc gót chân lên cao nhất có thể, nâng trọng lượng cơ thể lên phần đệm bàn chân.', 'Dừng một nhịp ở trên cùng, rồi từ từ hạ gót chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('standing-calves', 'standing calves', '{CALVES,HAMSTRINGS,GLUTES}', '{}', ARRAY['Đứng hai chân rộng bằng vai, mũi chân hướng về phía trước.', 'Nhấc gót chân khỏi sàn cao nhất có thể, đứng trên đầu ngón chân.', 'Giữ tư thế một nhịp, rồi từ từ hạ gót chân về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('standing-calves-calf-stretch', 'standing calves calf stretch', '{CALVES,HAMSTRINGS,GLUTES}', '{}', ARRAY['Đứng đối diện tường hoặc vật chắc, cách khoảng một sải tay.', 'Đặt hai tay lên tường hoặc vật ở ngang vai.', 'Lùi một chân về sau, giữ gót chân phẳng trên sàn.', 'Hơi gập đầu gối trước và nghiêng người về phía trước, giữ chân sau thẳng.', 'Bạn sẽ cảm thấy căng ở cơ bắp chân.', 'Giữ kéo giãn trong 20-30 giây.', 'Làm lại với chân còn lại.'], '{}', false, false, true),
  ('standing-hamstring-and-calf-stretch-with-strap', 'standing hamstring and calf stretch with strap', '{HAMSTRINGS,CALVES}', '{OTHER}', ARRAY['Đứng thẳng, hai chân rộng bằng vai.', 'Cầm dây bằng hai tay và quấn quanh phần đệm bàn chân.', 'Giữ chân thẳng và từ từ nghiêng người về phía trước từ hông, giữ lưng thẳng.', 'Cảm nhận căng ở cơ đùi sau và bắp chân.', 'Giữ kéo giãn trong 20-30 giây.', 'Thả kéo giãn và làm lại với chân còn lại.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('standing-lateral-stretch', 'standing lateral stretch', '{LATS,SHOULDERS,CORE}', '{}', ARRAY['Đứng hai chân rộng bằng vai, hơi gập gối.', 'Duỗi hai tay thẳng ra hai bên, song song sàn.', 'Từ từ nghiêng thân trên sang một bên, cảm nhận căng ở sườn và cơ xô.', 'Giữ kéo giãn trong 15-30 giây.', 'Trở về vị trí ban đầu và làm lại bên kia.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
  ('standing-pelvic-tilt', 'standing pelvic tilt', '{LOWER_BACK,CORE}', '{}', ARRAY['Đứng hai chân rộng bằng vai, hơi gập gối.', 'Đặt hai tay lên hông hoặc để thõng bên người.', 'Siết cơ bụng và xoay khung chậu về phía trước, đẩy lưng dưới về phía tường phía sau.', 'Giữ tư thế vài giây, rồi thả lỏng và trở về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
