  ('upper-back-stretch', 'upper back stretch', '{UPPER_BACK,SHOULDERS}', '{}', ARRAY['Đứng thẳng, hai chân rộng bằng vai.', 'Duỗi thẳng hai tay ra trước, song song sàn.', 'Đan các ngón tay và xoay lòng bàn tay ra xa thân.', 'Từ từ nâng hai tay lên qua đầu, giữ thẳng và song song với nhau.', 'Khi nâng tay, siết hai bả vai lại với nhau.', 'Giữ kéo giãn trong 15-30 giây, rồi thả và lặp lại.'], '{}', false, false, true),
  ('upward-facing-dog', 'upward facing dog', '{LOWER_BACK,SHOULDERS,CHEST}', '{}', ARRAY['Nằm sấp trên sàn, hai chân duỗi về phía sau.', 'Đặt hai tay trên sàn cạnh xương sườn dưới, các ngón tay hướng về phía trước.', 'Ấn mạnh hai tay xuống sàn và duỗi thẳng tay, nâng thân trên và đùi khỏi sàn.', 'Kéo vai ra sau và xuống dưới, mở ngực và ngẩng mắt lên trần.', 'Giữ tư thế vài nhịp thở, rồi từ từ hạ người về vị trí ban đầu.', 'Lặp lại đủ số lần mong muốn.'], '{}', false, false, true),
